INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(743, 'koKR', 'Groźne Wichrogniewne harpie', 'Dziękuję, że $gznalazłeś:znalazłaś; czas, by ze mną porozmawiać, $N. Jestem Ruul, wojownik i nauczyciel.$B$BNajwyraźniej $gosiągnąłeś:osiągnęłaś; już wiek, w którym trzeba przygotować się do prób, jeśli chcesz wyruszać dalej poza Mulgor.$B$BJeśli pragniesz sprawdzić swoją siłę, zacznij od odszukania Wichrogniewnych harpii na południowym wschodzie. Gnieżdżą się na zboczach gór, z dala od drogi.$B$BTo jedni z naszych odwiecznych wrogów tu, w Mulgorze, i będą dobrą miarą twoich umiejętności.', 'Przynieś 8 szponów wichrogniewnych harpii Ruulowi Orlemu Szponowi w Wiosce Krwawego Kopyta.', '', 'Wróć do Ruula Orlego Szponu w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(745, 'koKR', 'Ziemia dla wszystkich', '$N, wiele konfliktów rani tę ziemię. Mam nadzieję, że nie będziesz świadkiem tylu z nich, ilu ja widziałem. Jest jednak jeden, ku któremu chcę cię posłać. Pokaże ci, jak straszne dla ziemi może się stać nawet niewielkie zagrożenie, jeśli nikt go nie powstrzyma.$B$BGnole z Bladogrzywych osiedliły się na południe od Krwawego Kopyta i w jaskini na zachodzie. Lekceważą nasze próby porozumienia się z nimi i bez umiaru zabijają zwierzęta Mulgoru.$B$BSłowa nie są już odpowiedzią.', 'Zabij 10 garbarzy, 8 skórników i 5 kłusowników z Bladogrzywych, a następnie wróć do Baina Krwawego Kopyta w Wiosce Krwawego Kopyta.', '', 'Wróć do Baina Krwawego Kopyta w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(746, 'koKR', 'Krasnoludzkie wykopy', 'Na północnym zachodzie krasnoludy szykują miejsce wykopalisk. Wierzą, że w ziemi kryją się tajemnice, i to prawda, ale drążeniem i bezczeszczeniem ziemi nie zasłuży się na jej nauki.$B$BZbierz krasnoludzkie narzędzia do kopania, rozbij je i wróć do mnie z połamanymi narzędziami.$B$BNarzędzia możesz rozbić w kuźni. Znajdziesz ją w Gromowych Urwiskach, ale wystarczy każda kuźnia – nawet ta w obozie krasnoludów.', 'Zbierz 5 kilofów poszukiwacza.$B$BRozbij kilofy poszukiwacza w kuźni, aby otrzymać połamane narzędzia.$B$BPrzynieś 5 połamanych narzędzi Bainowi Krwawemu Kopytu w Wiosce Krwawego Kopyta.', '', 'Wróć do Baina Krwawego Kopyta w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(747, 'koKR', 'Początek łowów', 'Masz w sobie coś obiecującego i z pewnością dowiedziesz swej wartości przed plemieniem. Być może już wkrótce zostaniesz $gprzyjęty:przyjęta; w wielkim mieście Gromowych Urwisk. Zanim jednak to nastąpi, musisz dowieść swej wartości przed moim ojcem, wodzem Jastrzębim Wiatrem.$b$bTu, na Płaskowyżu Czerwonej Chmury, szczycimy się łowieckim kunsztem. Taureni polują z konieczności i dla sportu. Kończą nam się zapasy mięsa, a potrzebujemy też piór na odzienie. Zapoluj na pobliskie biegusy równinne i dowiedź swej wartości, uzupełniając zapasy wioski.', 'Grull Jastrzębi Wiatr z Obozu Naracze chce, żebyś $gprzyniósł:przyniosła; mu 7 piór biegusa równinnego i 7 porcji mięsa biegusa równinnego.', '', 'Wróć do Grulla Jastrzębiego Wiatru w Obozie Naracze w Mulgorze.', '', '', '', '', 0),
(748, 'koKR', 'Zatruta woda', 'Gobliny i ich słudzy skazili nasze święte studnie! Nie możemy na to pozwolić.$B$BAby oczyścić każdą studnię, muszę stworzyć totem oczyszczenia, a ty musisz zanieść go do studni i odprawić rytuał oczyszczenia.$B$BNajpierw stworzymy totem oczyszczenia dla Ujęcia Wody Zimowego Kopyta. Aby to uczynić, ziemia musi udzielić nam swej pomocy. Poluj na wilki preriowe dla ich łap i na dorosłe biegusy równinne dla ich szponów. Znajdziesz je na południowym zachodzie.$B$BWróć do mnie z łapami i szponami, $N.', 'Przynieś 6 łap wilka preriowego i 4 szpony biegusa równinnego Mullowi Gromorogowi w Wiosce Krwawego Kopyta.', '', 'Wróć do Mulla Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(749, 'koKR', 'Złupiona Karawana', 'Kilka dni temu natknęliśmy się na strzeżoną karawanę spółki Gitgeszeft, która ciągnęła północnym brzegiem Jeziora Kamiennego Byka. We wcześniejszej bitwie straciliśmy dwóch naszych, więc nie zwlekaliśmy z atakiem i zniszczyliśmy karawanę.$b$bZostawiliśmy ich skrzynie z zapasami, sądząc, że nasze pochodnie strawią wszystko, co cenne, ale skoro przy spalonych wozach widziano szabrowników spółki Gitgeszeft, może się myliliśmy.$b$bMoże udasz się do karawany i zbadasz zawartość skrzyń?', 'Morin Tropiciel Chmur chce, żebyś $gzbadał:zbadała; zawartość skrzyni z zapasami przy Złupionej Karawanie.', '', '', '', '', '', '', 0),
(750, 'koKR', 'Dalsze łowy', 'Tauren biegły w sztuce łowów wie, że zdobycz to nie tylko trofeum. Zwierzęta równin dają nam środki do przetrwania. Zrobisz spore wrażenie na starszyźnie, jeśli przyniesiesz wysoko cenione futra górskich kuguarów. Znajdziesz te zwierzęta czające się na wzgórzach na południu.$b$bNasze dzieci potrzebują odzienia, a namioty łatania.', 'Grull Jastrzębi Wiatr z Obozu Naracze chce, żebyś $gprzyniósł:przyniosła; mu 10 futer górskiego kuguara.', '', 'Wróć do Grulla Jastrzębiego Wiatru w Obozie Naracze w Mulgorze.', '', '', '', '', 0),
(751, 'koKR', 'Złupiona Karawana', 'Pod podważonym wiekiem kryje się ciasno upakowany zbiór rud i minerałów – kolejny dowód działalności górniczej spółki Gitgeszeft w Mulgorze. Z wierzchu wyjmujesz mocno związany plik papierów.$b$bZ pogórza na wschodzie ledwie dobiegają odgłosy pracy, a nad wielkim ogniskiem unosi się dym.', 'Zanieś dokumenty spółki Gitgeszeft Morinowi Tropicielowi Chmur w pobliżu Wioski Krwawego Kopyta.', '', '', '', '', '', '', 0),
(752, 'koKR', 'Skromne zadanie', 'Wszyscy członkowie plemienia mają udział w harmonii życia. Razem żyjemy i razem pracujemy.$b$bNasze wzajemne zobowiązania niosą ze sobą wielką odpowiedzialność. Proszę cię teraz o wykonanie skromnego zadania.$b$bMoja matka wyruszyła dziś rano po wodę do studni na południowy wschód od Naracze. Minęło już sporo czasu. Może sprawdzisz, co u niej, gdy ja zajmę się tu sprawami plemienia?', 'Wódz Jastrzębi Wiatr chce, żebyś $godszukał:odszukała; jego matkę przy studni na południowy wschód od Obozu Naracze.', '', '', '', '', '', '', 0),
(753, 'koKR', 'Skromne zadanie', 'Przeszłam w życiu wiele ścieżek i te stare nogi nie mają już dawnego wigoru. Wciąż mogę wypełniać swoje obowiązki wobec plemienia. Po prostu czasem starej kobiecie zajmuje to trochę dłużej.$b$bAle wyglądasz na $gchętnego:chętną; do pracy. Wystawmy tę młodzieńczą werwę na próbę. Weź ze studni dzban na wodę i zanieś go mojemu synowi, wodzowi, do Obozu Naracze.$b$bPamiętaj, że nawet najskromniejsze zadanie może zyskać uznanie starszyzny.', 'Weź ze studni dzban na wodę.$b$bZanieś dzban wodzowi Jastrzębiemu Wiatrowi do Obozu Naracze, który leży na północny zachód od studni.', '', 'Wróć do wodza Jastrzębiego Wiatru w Obozie Naracze w Mulgorze.', '', '', '', '', 0),
(754, 'koKR', 'Oczyszczenie Zimowego Kopyta', 'Wykonałem totem, który oczyści Ujęcie Wody Zimowego Kopyta. Teraz musisz zanieść go do studni i odprawić rytuał oczyszczenia. Znajdziesz ją na południowym wschodzie, strzeżoną przez podłe gobliny!$B$BNie będzie to łatwe zadanie, ale musisz je wykonać, jeśli mamy kiedykolwiek znów korzystać z jej wód.$B$BPowodzenia, $N.', 'Użyj totemu oczyszczenia Zimowego Kopyta przy Ujęciu Wody Zimowego Kopyta, a następnie wróć do Mulla Gromoroga.', 'Oczyść Ujęcie Wody Zimowego Kopyta', 'Wróć do Mulla Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(755, 'koKR', 'Obrzędy Matki Ziemi', 'Twoja gotowość do wykonania skromnego zadania dla taurenów z Naracze i twój zapał do nauki to szlachetne cechy, $n. Wierzę, że pewnego dnia w Gromowych Urwiskach będą cię sławić jako $gwielkiego bohatera:wielką bohaterkę;.$b$bZanim to nastąpi, musisz przejść Obrzędy Matki Ziemi, a są trzy.$b$bPierwszą próbą jest Obrzęd Siły. Udaj się do jasnowidza Szarego Języka i powiedz mu, że przysyła cię wódz Jastrzębi Wiatr.$b$bSiedzibę jasnowidza znajdziesz wśród wzgórz, dokładnie na południe od Obozu Naracze.', 'Udaj się do jasnowidza Szarego Języka, który mieszka na wzgórzach dokładnie na południe od Obozu Naracze.', '', '', '', '', '', '', 0),
(756, 'koKR', 'Totem Gromorogich', 'Aby stworzyć totem oczyszczenia Gromorogich, musisz zebrać pazury drapieżników z równin Mulgoru. Poluj na tropicieli prerii i nizinne kuguary dla ich pazurów, a potem wróć do mnie.$B$BTropicieli prerii i nizinne kuguary znajdziesz na wschodzie i zachodzie.', 'Przynieś 6 pazurów tropiciela prerii i 6 pazurów kuguara Mullowi Gromorogowi.', '', 'Wróć do Mulla Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(757, 'koKR', 'Obrzęd Siły', 'Obrzędy Matki Ziemi to kroki, które młody tauren musi przejść, by zyskać szacunek w Gromowych Urwiskach.$b$bNajpierw musisz przejść Obrzęd Siły. W tej próbie musisz dowieść swej odwagi, zabijając wrogów plemienia.$b$bSierściogrzbieci z Wąwozu Ostrych Cierni na wschodzie wdzierają się na ziemie naszego plemienia. Urządzają zasadzki na naszych łowców i nocą okradają wioskę.$b$bOkaż męstwo, zabijając tych nikczemników, i wróć do wodza w Obozie Naracze z ich pasami jako dowodem twoich czynów.', 'Zabijaj Sierściogrzbietów w Wąwozie Ostrych Cierni i przynieś 8 pasów Sierściogrzbietów wodzowi Jastrzębiemu Wiatrowi w Obozie Naracze.', '', 'Wróć do wodza Jastrzębiego Wiatru w Obozie Naracze w Mulgorze.', '', '', '', '', 0),
(758, 'koKR', 'Oczyszczenie Gromorogich', 'Totem jest gotowy, $N. I znów to ty musisz odprawić rytuał oczyszczenia.$B$BUdaj się do Ujęcia Wody Gromorogich na północ od wioski i użyj w rytuale totemu oczyszczenia Gromorogich. Gdy to zrobisz, wróć do mnie.$B$BNiech prowadzą cię duchy.', 'Użyj totemu oczyszczenia Gromorogich przy Ujęciu Wody Gromorogich, a następnie wróć do Mulla.', 'Oczyść Ujęcie Wody Gromorogich', 'Wróć do Mulla Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(759, 'koKR', 'Totem Dzikogrzywych', 'Pozostała już tylko jedna studnia do oczyszczenia, nazwana na cześć klanu Dzikogrzywych. Aby ta studnia stała się czysta, ziemia musi ofiarować zęby groźnego drapieżnika – wilka preriowego alfy. Znajdź alfy na północy, a gdy skończysz łowy, wróć do mnie.$B$BAlfy często krążą u podnóża naszego potężnego miasta, Gromowych Urwisk.', 'Przynieś 8 zębów alfy z prerii Mullowi Gromorogowi w Wiosce Krwawego Kopyta.', '', 'Wróć do Mulla Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(760, 'koKR', 'Oczyszczenie Dzikogrzywych', 'O tym, jak $goczyściłeś:oczyściłaś; studnie Zimowego Kopyta i Gromorogich, mówią już duchy, $gmłody:młoda; $N. Totem Dzikogrzywych jest gotowy, a przed tobą ostatnie zadanie.$B$BUjęcie Wody Dzikogrzywych leży na północ od Gromowych Urwisk. Odpraw rytuał! Ulecz ziemię z goblińskich trucizn! Niech znów popłynie czysta woda!', 'Użyj totemu oczyszczenia Dzikogrzywych przy Ujęciu Wody Dzikogrzywych, a następnie wróć do Mulla Gromoroga.', 'Oczyść Ujęcie Wody Dzikogrzywych', 'Wróć do Mulla Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(761, 'koKR', 'Polowanie na pikujące', 'Pikujący to przebiegły ptak, trudny do wytropienia i upolowania. Zbiór lotek pikujących to dla łowcy odznaka sprytu i determinacji.$B$BJeśli chcesz podjąć się tego zadania, wyrusz na równiny i zapoluj na pikujące.$B$BPrzynieś mi ich lotki i przysporz chwały swojemu klanowi.$B$BPikujące można spotkać w całym Mulgorze, ale trzeba bystrych oczu, by je dostrzec, i szybkich kopyt, by je dogonić.', 'Przynieś 8 trofeowych lotek pikującego Harkenowi Totemowi Wiatru w Wiosce Krwawego Kopyta.', '', 'Wróć do Harkena Totemu Wiatru w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(763, 'koKR', 'Obrzędy Matki Ziemi', 'Aby kontynuować Obrzędy Matki Ziemi, musisz przejść jeszcze dwie próby. Czas poszerzyć swoje doświadczenie, $n.$b$bUdaj się do Wioski Krwawego Kopyta i odszukaj wodza, Baina Krwawego Kopyta, syna Kairna. Tam będziesz $gmógł:mogła; kontynuować swoją podróż i zyskać uznanie starszyzny Gromowych Urwisk.$b$bZanieś ten totem Bainowi. Rozpozna moje rzeźbienia i pomoże ci na twojej ścieżce.$b$bIdź drogą wychodzącą z Obozu Naracze i ruszaj bez zwłoki. Nie zbaczaj z niej, bo zabłądzisz.', 'Zanieś totem Jastrzębiego Wiatru Bainowi Krwawemu Kopytu w Wiosce Krwawego Kopyta. Idź drogą wychodzącą z Obozu Naracze.', '', '', '', '', '', '', 0),
(764, 'koKR', 'Spółka Gitgeszeft', 'To wyjaśnia, skąd w Mulgorze tylu pracowników i tyle sprzętu spółki Gitgeszeft. Te gobliny... ich spółka rozrasta się szybciej, niż wychodzi im to na dobre. Jak to mówią: pokaż goblinowi coś cennego, a zaraz usłyszysz brzęk szal wagi.$b$bChciwe z nich stworzonka. Na nieszczęście dla ich przedsięwzięcia my, taureni, nie możemy pozwolić, by prowadzili swoje interesy na naszych ziemiach. Udaj się do ich kopalni na północny wschód od złupionej karawany i daj im jasno do zrozumienia, co o tym sądzimy.', 'Zabij 14 robotników i 6 kierowników spółki Gitgeszeft dla Morina Tropiciela Chmur z Wioski Krwawego Kopyta.', '', 'Wróć do Morina Tropiciela Chmur w Mulgorze.', '', '', '', '', 0),
(765, 'koKR', 'Kierownik Fizsprocket', 'Według dokumentów, które $gocaliłeś:ocaliłaś; z karawany, spółka Gitgeszeft ułożyła wiele planów, by wypędzić nas z naszych ziem i swobodnie je grabić.$b$bTo, jak nisko gotowi są upaść, by osiągnąć swoje cele, budzi we mnie wstręt i oburzenie. Chcę, by mózg tych planów zginął. Nazywa się Kierownik Fizsprocket, a znajdziesz go w kopalni spółki Gitgeszeft na wschód od złupionej karawany. Przynieś mi jego notatnik, zobaczymy, czy dowiemy się z niego czegoś przydatnego.', 'Zabij Kierownika Fizsprocketa i zanieś jego notatnik Morinowi Tropicielowi Chmur w Wiosce Krwawego Kopyta.', '', 'Wróć do Morina Tropiciela Chmur w Mulgorze.', '', '', '', '', 0),
(766, 'koKR', 'Mazzranache', 'Mój dziadek opowiadał mi o swoich walkach z biegusem zwanym Mazzranache. Mówił o jego demonicznych czerwonych oczach, ostrych jak brzytwa szponach i jadowitym ukąszeniu.$b$bJak chciał los, podczas wędrówki przez równiny natknąłem się na niego, a on paskudnie ugryzł mnie w ramię. Był tak straszny, jak opisywał go dziadek. Aby oczyścić ranę z zakażenia, będę potrzebował kilku trudno dostępnych części zwierząt: serca wilka, kości udowej kuguara, łuski biegusa równinnego i żołądka pikującego.$b$bPośpiesz się, czas nagli.', 'Przynieś serce wilka preriowego, kość udową nizinnego kuguara, łuskę biegusa równinnego i żołądek pikującego Maurowi Przywoływaczowi Deszczu w Wiosce Krwawego Kopyta.', '', 'Wróć do Maura Przywoływacza Deszczu w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(767, 'koKR', 'Obrzęd Wizji', 'Obrzęd Wizji, jeden z Obrzędów Matki Ziemi, pomoże ci zdobyć szacunek starszyzny Gromowych Urwisk.$b$bNasz lud nauczył się, że ziemia jest naszą najświętszą żywicielką. Aby wziąć udział w rytualnej wizji, musisz porozmawiać z duchowym przewodnikiem wioski, Zarlmanem Dwa Księżyce.', 'Porozmawiaj z Zarlmanem Dwa Księżyce w Wiosce Krwawego Kopyta.', '', '', '', '', '', '', 0),
(770, 'koKR', 'Płaszcz naznaczony przez demona', 'Postrzępiona skóra Upiornego Wycia wciąż nosi straszliwą ranę, którą wilk odniósł w walkach z Płonącym Legionem.$B$BByć może ktoś w Wiosce Krwawego Kopyta powinien się dowiedzieć o śmierci Upiornego Wycia...', 'Znajdź kogoś, kto wie coś o Upiornym Wyciu.', '', '', '', '', '', '', 0),
(771, 'koKR', 'Obrzęd Wizji', 'Aby przejść Obrzęd Wizji, musisz zebrać składniki potrzebne do przyrządzenia Wody jasnowidzów.$b$bBędę potrzebował kamieni studziennych, które znajdziesz przy studniach w Mulgorze. Połączę je z bursztynowymi żołędziami, które spadają pod potężnymi drzewami naszej krainy.$b$bTe składniki kryją w sobie magię, a uwarzone i wypite przed ogniskiem plemiennym, sprowadzą na ciebie wizję. Podążaj za nią, a doprowadzi cię do kolejnego kroku tej świętej wędrówki.', 'Zbierz 2 kamienie studzienne i 2 bursztynowe żołędzie i zanieś je Zarlmanowi Dwa Księżyce w Wiosce Krwawego Kopyta.', '', 'Wróć do Zarlmana Dwa Księżyce w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(772, 'koKR', 'Obrzęd Wizji', 'Oto Woda jasnowidzów.$b$bGdy będziesz $ggotów:gotowa;, wypij ją przy ognisku plemiennym. Gdy przyjmiesz świętą wodę, minie kilka chwil, zanim przed ogniem ukaże się wizja.$b$bWtedy od ciebie zależy, czy podążysz za nią ku swemu przeznaczeniu...', 'Wypij Wodę jasnowidzów przed ogniskiem plemiennym w Wiosce Krwawego Kopyta, a gdy pojawi się wizja, podążaj za nią.', '', '', '', '', '', '', 0),
(773, 'koKR', 'Obrzęd Mądrości', 'Aby zyskać uznanie starszyzny Gromowych Urwisk, musisz teraz przejść Obrzęd Mądrości.$b$bSkoro $gprzeszedłeś:przeszłaś; już Obrzęd Wizji, duchy przodków z Czerwonych Skał udzielą ci błogosławieństwa naszych przodków. Tylko ci, którzy pili Wodę jasnowidzów, mogą je otrzymać.$b$bUdaj się na wschód od Gromowych Urwisk, do Czerwonych Skał, i odszukaj Ducha przodków, $n.', 'Udaj się do Czerwonych Skał na wschód od Gromowych Urwisk i porozmawiaj z Duchem przodków.', '', '', '', '', '', '', 0),
(775, 'koKR', 'Podróż do Gromowych Urwisk', 'Odtąd będziesz $gczczony:czczona; w naszym wielkim mieście. Na ten zaszczyt zasługuje każdy, kto jest godzien przejść Obrzędy Matki Ziemi.$b$bW ostatnim zadaniu odszukaj naszego szlachetnego przywódcę, Kairna Krwawe Kopyto, który mieszka na najwyższym płaskowyżu Gromowych Urwisk.', 'Porozmawiaj z Kairnem Krwawym Kopytem w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(776, 'koKR', 'Obrzędy Matki Ziemi', '$GPrzeszedłeś:Przeszłaś; Obrzędy Matki Ziemi i $gzasłużyłeś:zasłużyłaś; na miejsce w Gromowych Urwiskach.$b$bAle by utrzymać miejsce, o które tak ciężko $gzabiegałeś:zabiegałaś;, musisz wciąż dowodzić swej wartości przed swoim ludem.$b$bJesteśmy łowcami, $n. W dole, w Mulgorze, żyje potężny kodo o imieniu Arra\'chea. Pokaż mi swój kunszt w tropieniu i polowaniu, przynosząc mi Róg Arra\'chea.', 'Kairn Krwawe Kopyto w Gromowych Urwiskach chce, żebyś $gprzyniósł:przyniosła; mu Róg Arra\'chea.', '', 'Wróć do Kairna Krwawego Kopyta na Złotych Równinach w Mulgorze.', '', '', '', '', 0),
(780, 'koKR', 'Bojowe dziki', 'Bojowe dziki z Wąwozu Ostrych Cierni na wschodzie wdzierają się na łowiska naszego plemienia. Kolcozwierze z Sierściogrzbietów, z którymi toczymy wojnę, szkolą je, by były złośliwe.$b$bIdź, zabij te plugawe stworzenia i przynieś trochę ryjów i udźców, byśmy mogli ugotować gulasz dla naszych młodych.', 'Grull Jastrzębi Wiatr z Obozu Naracze chce, żebyś zabijał bojowe dziki i $gprzyniósł:przyniosła; mu 8 ryjów bojowego dzika i 8 udźców bojowego dzika.', '', 'Wróć do Grulla Jastrzębiego Wiatru w Obozie Naracze w Mulgorze.', '', '', '', '', 0),
(781, 'koKR', 'Atak na Obóz Naracze', 'Po uważnym przestudiowaniu mapy uświadamiasz sobie, że $gznalazłeś:znalazłaś; plany długotrwałego oblężenia Obozu Naracze, sporządzone przez wodza wojennego Sierściogrzbietów.$b$bWódz Jastrzębi Wiatr z pewnością zechce się o tym dowiedzieć!', 'Zanieś plany ataku Sierściogrzbietów wodzowi Jastrzębiemu Wiatrowi w Obozie Naracze.', '', '', '', '', '', '', 0),
(833, 'koKR', 'Święty pochówek', 'Tylko najmężniejsi taureni spoczywają w Czerwonych Skałach, naszym świętym miejscu pochówku. To zaszczyt przyznawany wielkim wojownikom, którzy pomogli założyć Gromowe Urwiska i ich bronić, oraz tym, którzy oddali życie za dobro swoich plemion i wodzów.$b$bLecz zdaje się, że na naszą świętą ziemię wkradło się plugawe zagrożenie. Banda intruzów z Sierściogrzbietów pustoszy groby, a ja jestem zbyt stary i zbyt słaby, by ich przegnać.$b$bTrzeba ich wypędzić siłą, $n.', 'Wiedzący Deszczowy Totem chce, żebyś $gzabił:zabiła; 8 intruzów z Sierściogrzbietów w Czerwonych Skałach.', '', 'Wróć do Wiedzącego Deszczowego Totemu w Czerwonych Skałach w Mulgorze.', '', '', '', '', 0),
(854, 'koKR', 'Podróż na Rozdroże', 'Przewidziałem twoje przybycie, $gmłody:młoda; $N. Choć może nie jesteś już $gtaki młody:taka młoda;.$B$BMyślę, że nadszedł czas, byś $gwyruszył:wyruszyła; w głąb tej krainy. Wyczuwam, że pisane ci są wielkie rzeczy.$B$BMusisz odszukać Rozdroże, bo nasze losy splotły się z losami orków, a oni potrzebują pomocy. Idź tą drogą na wschód, a potem na północ, aż do Rozdroża. Odszukaj w jego murach Thorka – ma on błogosławieństwo Matki Ziemi.', 'Porozmawiaj z Thorkiem na Rozdrożu na Pustkowiach.', '', '', '', '', '', '', 0),
(861, 'koKR', 'Droga łowcy', 'Widzę, że pragniesz odkrywać świat. Ja też kiedyś miałem w sobie żądzę wędrówki...$B$BWędrówki i łowów. Bo łowy to dla taurena największy zaszczyt.$B$BJeśli naprawdę pragniesz podążać drogą łowcy, Melor Kamienne Kopyto może wskazać ci ścieżkę. Znajdziesz go w Gromowych Urwiskach, na Wzniesieniu Myśliwego.$B$BA by pokazać mu swój kunszt i determinację, przynieś mu pazury nizinnych drapieżców z Mulgoru. Są twarde i przebiegłe – to godna zdobycz dla $gmłodego łowcy:młodej łowczyni; na łowieckiej ścieżce.', 'Przynieś 4 pazury nizinnego drapieżcy Melorowi Kamiennemu Kopytu w Gromowych Urwiskach.', '', 'Wróć do Melora Kamiennego Kopyta na Wzniesieniu Myśliwego w Gromowych Urwiskach.', '', '', '', '', 0),
(1462, 'koKR', '', '', 'Porozmawiaj z jasnowidzką Kruczym Piórem, aby otrzymać kolejną saptę ziemi.', '', '', '', '', '', '', 0),
(1519, 'koKR', '', 'Nadszedł czas, $N. Twoje ciało dojrzewa i nabiera sił, a twój duch jest trwały jak ziemia. Widzę to w tobie – już masz w sobie mądrość.$B$BZiemia prowadzi nasz lud i przemawia do nas, a z czasem przemówi i do ciebie. Musisz jednak przejść próbę. Jeśli jesteś $ggotów:gotowa;, ujrzysz rzeczy znane tylko naszemu rodowi.$B$BOdszukaj szamanki Sierściogrzbietów w ich wąwozie na wschodzie i zabierz im maść, której używają w swoich rytuałach. Wróć do mnie dopiero wtedy, gdy zbierzesz jej dość na własny wywar.', 'Przynieś 2 porcje rytualnej maści jasnowidzce Kruczemu Pióru w Obozie Naracze.', '', 'Wróć do jasnowidzki Kruczego Pióra na Płaskowyżu Czerwonej Chmury w Mulgorze.', '', '', '', '', 0),
(1656, 'koKR', 'Niedokończone zadanie', '$N, proszę, błagam cię, pomożesz mi? Nie skończyłam jeszcze swoich zadań tu, na płaskowyżu – jestem w trakcie Obrzędu Siły – a ojciec poprosił mnie, żebym zaniosła te futra do karczmy w Wiosce Krwawego Kopyta.$B$BNie mam dość sił, by ukończyć i obrzęd, i to zadanie dla ojca. Czy $gmógłbyś:mogłabyś; pójść tam za mnie?$B$BKarczma jest przyjemna i to idealne miejsce na odpoczynek podczas długich podróży. Na pewno przyznasz mi rację, gdy ją zobaczysz.', 'Zanieś wiązkę futer karczmarzowi Kauthowi w Wiosce Krwawego Kopyta.', '', '', '', '', '', '', 0),
(2984, 'koKR', '', 'Wiele czasu minęło od twojej ostatniej próby, $N. Dotąd $gwykazywałeś:wykazywałaś; cierpliwość w nauce, ale nadszedł czas, byś $gpoznał:poznała; więcej. Nadszedł czas, byś $gpoznał:poznała; zniszczenie... i chaos. Żywioł ognia może stać się twój, jeśli pojmiesz go i będziesz $ggotów:gotowa; za to zapłacić.$B$BOdszukaj Kranala Fissa na Pustkowiach. Mieszka w małym domostwie na północ od Rozdroża, ale uważaj – jeśli dotrzesz do ziem nocnych elfów, $gzaszedłeś:zaszłaś; za daleko.', '', '', '', '', '', '', '', 0),
(2986, 'koKR', '', 'Wiele czasu minęło od twojej ostatniej próby, $N. Dotąd $gwykazywałeś:wykazywałaś; cierpliwość w nauce, ale nadszedł czas, byś $gpoznał:poznała; więcej. Nadszedł czas, byś $gpoznał:poznała; czystość wody.$B$BOdszukaj Islen Wodowieszczkę na Pustkowiach. Mieszka na wschodnim wybrzeżu, na południe od Rzeki Południowej Furii i Zapadki. Znajdziesz ją w jej chacie rybackiej. Powodzenia, $N.', '', '', '', '', '', '', '', 0),
(3091, 'koKR', 'Prosty liścik', 'Przed chwilą szukała cię posłanniczka, $N. Chyba przysłał ją nauczyciel wojowników, Harutt. Jeśli to liścik od Harutta, nie zwlekałbym z jego przeczytaniem.$B', 'Przeczytaj prosty liścik i porozmawiaj z Haruttem Gromorogiem w Obozie Naracze.', '', '', '', '', '', '', 0),
(3092, 'koKR', 'Wyryta notatka', 'Przed chwilą szukała cię posłanniczka, $N. Chyba przysłał ją nauczyciel łowców, Lanka. Jeśli to notatka od Lanki, nie zwlekałbym z jej przeczytaniem.$B', 'Przeczytaj wyrytą notatkę i porozmawiaj z Lanką Dalekostrzałem na Płaskowyżu Czerwonej Chmury.', '', '', '', '', '', '', 0),
(3093, 'koKR', 'Liścik z wyrytymi runami', 'Przed chwilą szukała cię posłanniczka, $N. Chyba przysłała ją nauczycielka szamanów, Meela. Jeśli to liścik od Meeli, nie zwlekałbym z jego przeczytaniem.$B', 'Przeczytaj liścik z wyrytymi runami i porozmawiaj z Meelą Świtokrocz w Obozie Naracze.', '', '', '', '', '', '', 0),
(3094, 'koKR', 'Zielony liścik', 'Przed chwilą szukała cię posłanniczka, $N. Chyba przysłał ją nauczyciel druidów, Gart. Jeśli to liścik od Garta, nie zwlekałbym z jego przeczytaniem.$B', 'Przeczytaj zielony liścik i porozmawiaj z Gartem Mglistym Biegiem w Obozie Naracze.', '', '', '', '', '', '', 0),
(3376, 'koKR', 'Złam Ostrokła!', '$N – słyszałam o tobie, $gprzybyszu:przybyszko;. Może to ty nam pomożesz tam, gdzie inni zawiedli.$B$BMy, taureni, wykroiliśmy sobie dom z tej ziemi, ale nie bez ceny. Kolcozwierze z Sierściogrzbietów z Wąwozu Ostrych Cierni, na czele z wodzem Ostrokłem Cierniofutrym, utrudniają nam życie nieustanną wojną. Rozkazuję ci przynieść mi głowę ich wodza!$B$BZnajdziesz go w wąwozie na wschodzie, w ich prowizorycznej wiosce.', 'Przynieś głowę wodza Ostrokła Cierniofutrego Wojowniczce Wietrzne Pióro na Płaskowyżu Czerwonej Chmury.', '', 'Wróć do Wojowniczki Wietrzne Pióro w Obozie Naracze w Mulgorze.', '', '', '', '', 0),
(5844, 'koKR', '', 'Witaj w World of Warcraft!$B$BW podziękowaniu za zakup edycji kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Vornowi Niebowidzowi w Wiosce Krwawego Kopyta. Otrzymasz wtedy prezent: małego towarzysza, który dołączy do ciebie w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy miłego pobytu w świecie World of Warcraft!', 'Zanieś bon podarunkowy z Wioski Krwawego Kopyta Vornowi Niebowidzowi w Wiosce Krwawego Kopyta.', '', '', '', '', '', '', 0),
(5926, 'koKR', '', 'Wybacz, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Turak Runiczny Totem rozgłosił, iż chce z tobą porozmawiać. Wygląda na to, że twoje szkolenie druida zaraz nabierze nowego życia, a on będzie cię szkolić osobiście. Turak jest jednym z pomocników arcydruida. Uchodzi za mądrego i cierpliwego druida, powinien więc dobrze cię nauczyć.$B$BZnajdziesz go w Gromowych Urwiskach, w głównym namiocie Kręgu Cenariona na Wzniesieniu Starszych.', 'Porozmawiaj z Turakiem Runicznym Totemem na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(5927, 'koKR', '', 'Wybacz, $gprzyjacielu:przyjaciółko;...$B$BDoszły mnie słuchy, że Turak Runiczny Totem rozgłosił, iż chce z tobą porozmawiać. Wygląda na to, że twoje szkolenie druida zaraz nabierze nowego życia, a on będzie cię szkolić osobiście. Turak jest jednym z pomocników arcydruida. Uchodzi za mądrego i cierpliwego druida, powinien więc dobrze cię nauczyć.$B$BZnajdziesz go w Gromowych Urwiskach, w głównym namiocie Kręgu Cenariona na Wzniesieniu Starszych.', 'Porozmawiaj z Turakiem Runicznym Totemem na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(6061, 'koKR', '', 'Jako tauren musisz wiernie trzymać się tradycji naszych przodków, walcząc z potężnymi stworzeniami. Pokonując je, przyjmujemy w siebie ich duchy, co przybliża nas do Matki Ziemi.$B$BTak samo oswojenie zwierzęcia, które walczy u naszego boku, pomaga nam stać się jednym z otaczającą nas naturą. Z czasem nauczysz się oswajać zwierzę, które $gsam:sama; wybierzesz. Ale wszystko wymaga ćwiczeń, a ty wiele musisz się jeszcze nauczyć. Zacznij od wzięcia tej różdżki oswajania. Musisz oswoić dorosłego biegusa równinnego.', 'Użyj różdżki oswajania, aby oswoić dorosłego biegusa równinnego. Poćwicz swoje umiejętności, a potem oddaj różdżkę oswajania Yawowi Ostrogrzywemu w Wiosce Krwawego Kopyta.', 'Oswój dorosłego biegusa równinnego', 'Wróć do Yawa Ostrogrzywego w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(6087, 'koKR', '', 'Masz ognistego ducha, $gmłody łowco:młoda łowczyni;, i już wyczekujesz kolejnego wyzwania.$B$BTwoim następnym zadaniem jest zdobyć towarzysza w postaci wilka zwanego tropicielem prerii. To stworzenie jest szybkie i nieustraszone. Biorąc je sobie za towarzysza, musisz przyjąć też te cechy.$B$BW walce przekonasz się, jak ty i twój towarzysz stajecie się drużyną. W końcu musicie działać jak jedno, mięsień przy mięśniu.$B$BOto różdżka oswajania, $N. Oswój tropiciela prerii i poćwicz swoje umiejętności.', 'Użyj różdżki oswajania, aby oswoić tropiciela prerii. Poćwicz swoje umiejętności, a potem oddaj różdżkę oswajania Yawowi Ostrogrzywemu w Wiosce Krwawego Kopyta.', 'Oswój tropiciela prerii', 'Wróć do Yawa Ostrogrzywego w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(6088, 'koKR', '', 'Ostatnie zadanie, jakie mam dla ciebie, wymaga oswojenia stworzenia, które zamieszkuje niebo. Pikujący to trudny przeciwnik, ale jako sojusznik użyczy ci swoich ostrych ataków i groźnej postawy.$B$BZ woli Matki Ziemi, gdy wrócisz, obdarzę cię umiejętnościami potrzebnymi do oswojenia wybranego zwierzęcia na towarzysza. To stworzenie stawi czoła tym samym wyzwaniom co ty i razem z tobą będzie zdobywać doświadczenie. Pokażę ci też, jak je przywoływać i odsyłać, kiedy zechcesz.$B', 'Użyj różdżki oswajania, aby oswoić pikującego. Poćwicz swoje umiejętności, a potem oddaj różdżkę oswajania Yawowi Ostrogrzywemu w Wiosce Krwawego Kopyta.', 'Oswój pikującego', 'Wróć do Yawa Ostrogrzywego w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(6089, 'koKR', '', 'Masz już moc oswajania zwierząt, ale musisz też zdobyć umiejętność ich szkolenia.$B$BUdaj się do Gromowych Urwisk. Musisz tam porozmawiać z jednym z naszych najbardziej czczonych łowców, Holtem Gromorogiem. Jeśli uzna cię za $ggodnego:godną;, da ci zdolność szkolenia twojego nowego towarzysza.$B$BHolt pokonał najpotężniejsze i najstraszniejsze bestie Azeroth i sam dowodzi wieloma silnymi stworzeniami. Jego więź z Matką Ziemią jest silna i wiele możesz się od niego nauczyć. Powodzenia, $N.$B', 'Porozmawiaj z Holtem Gromorogiem na Wzniesieniu Myśliwego w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(7662, 'koKR', 'Nowy kodo – modry', '', '', '', 'Wróć do Harba Szponiastego Kopyta w Mulgorze.', '', '', '', '', 0),
(7663, 'koKR', 'Nowy kodo – zielony', '', '', '', 'Wróć do Harba Szponiastego Kopyta w Mulgorze.', '', '', '', '', 0),
(7945, 'koKR', '', '„Twój los czeka na ciebie przy Skale Bladogrzywych”.$B$BPrzepowiednia, którą wręczył ci Sayge, jest lekko ciepła w dotyku. Gdy mocno ją ściskasz, widzisz obraz Skały Bladogrzywych w Mulgorze. Gdy skupiasz się bardziej na obrazie, dostrzegasz pniak stojący blisko wejścia do jaskini.$B', 'Udaj się do Skały Bladogrzywych w Mulgorze i odszukaj swój los.', '', '', '', '', '', '', 0),
(11129, 'koKR', 'Kyle zaginął!', 'Pomocy, $N! Mój ukochany szczeniak, Kyle, uciekł! Jestem pewien, że biega gdzieś po Wiosce Krwawego Kopyta, zagubiony i głodny.$B$BCzy odnajdziesz go i nakarmisz? Gdy się naje, uspokoi się i wróci do domu.$B$BAby go nakarmić, musisz zdobyć jedzenie. Jego ulubiony przysmak to delikatne mięso biegusa. Wybierz się na wschód, a na pewno znajdziesz mnóstwo biegusów. Upoluj jednego i zanieś jego soczyste mięso Kyle\'owi. Gdy zobaczysz Kyle\'a w wiosce, połóż mięso na ziemi, a on na pewno do ciebie przyjdzie.', 'Ahab Pszeniczne Kopyto z Wioski Krwawego Kopyta w Mulgorze chce, żebyś $gnakarmił:nakarmiła; jego ukochanego szczeniaka, Kyle\'a Rozszalałego.$B$BNakarm Kyle\'a delikatnym mięsem biegusa i wróć do Ahaba Pszenicznego Kopyta.', '', 'Wróć do Ahaba Pszenicznego Kopyta w Mulgorze.', '', 'Kyle nakarmiony', '', '', 0),
(14087, 'koKR', 'Nauka jazdy w Mulgorze', 'Tę ulotkę reklamującą naukę jazdy i sprzedaż wierzchowców przysłał Kar Burzowa Pieśń.$B$BKara można znaleźć w Wiosce Krwawego Kopyta w Mulgorze.', 'Zanieś ulotkę Karowi Burzowej Pieśni w Wiosce Krwawego Kopyta w Mulgorze.', '', 'Wróć do Kara Burzowej Pieśni w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(14436, 'koKR', 'Krasnoludzkie wykopy', 'Na północnym zachodzie krasnoludy szykują miejsce wykopalisk. Wierzą, że w ziemi kryją się tajemnice, i to prawda, ale drążeniem i bezczeszczeniem ziemi nie zasłuży się na jej nauki.$B$BZbierz krasnoludzkie narzędzia do kopania, rozbij je i wróć do mnie z połamanymi narzędziami.$B$BNarzędzia możesz rozbić w kuźni. Znajdziesz ją w Gromowych Urwiskach, ale wystarczy każda kuźnia – nawet ta w obozie krasnoludów.', 'Zbierz 5 kilofów poszukiwacza.$B$BRozbij kilofy poszukiwacza w kuźni, aby otrzymać połamane narzędzia.$B$BPrzynieś 5 połamanych narzędzi Ahmowi Gromorogowi w Wiosce Krwawego Kopyta.', '', 'Wróć do Ahma Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(14437, 'koKR', 'Obrzędy Matki Ziemi', 'Aby kontynuować Obrzędy Matki Ziemi, musisz przejść jeszcze dwie próby. Czas poszerzyć swoje doświadczenie, $n.$b$bUdaj się do Wioski Krwawego Kopyta i odszukaj Ahma Gromoroga. Tam będziesz $gmógł:mogła; kontynuować swoją podróż i zyskać uznanie starszyzny Gromowych Urwisk.$b$bZanieś ten totem Ahmowi. Rozpozna moje rzeźbienia i pomoże ci na twojej ścieżce.$b$bIdź drogą wychodzącą z Obozu Naracze i ruszaj bez zwłoki. Nie zbaczaj z niej, bo zabłądzisz.', 'Zanieś totem Jastrzębiego Wiatru Ahmowi Gromorogowi w Wiosce Krwawego Kopyta. Idź drogą wychodzącą z Obozu Naracze.', '', 'Wróć do Ahma Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(14438, 'koKR', 'Ziemia dla wszystkich', '$N, wiele konfliktów rani tę ziemię. Mam nadzieję, że nie będziesz świadkiem tylu z nich, ilu widziała nasza starszyzna. Jest jednak jeden, ku któremu chcę cię posłać. Pokaże ci, jak straszne dla ziemi może się stać nawet niewielkie zagrożenie, jeśli nikt go nie powstrzyma.$B$BGnole z Bladogrzywych osiedliły się na południe od Krwawego Kopyta i w jaskini na zachodzie. Lekceważą nasze próby porozumienia się z nimi i bez umiaru zabijają zwierzęta Mulgoru.$B$BSłowa nie są już odpowiedzią.', 'Zabij 10 garbarzy, 8 skórników i 5 kłusowników z Bladogrzywych, a następnie wróć do Ahma Gromoroga w Wiosce Krwawego Kopyta.', '', 'Wróć do Ahma Gromoroga w Wiosce Krwawego Kopyta w Mulgorze.', '', '', '', '', 0),
(14439, 'koKR', 'Podróż do Gromowych Urwisk', 'Odtąd będziesz $gczczony:czczona; w naszym wielkim mieście. Na ten zaszczyt zasługuje każdy, kto jest godzien przejść Obrzędy Matki Ziemi.$b$bW ostatnim zadaniu odszukaj naszego młodego przywódcę, Baina Krwawe Kopyto, który mieszka na najwyższym płaskowyżu Gromowych Urwisk.', 'Porozmawiaj z Bainem Krwawym Kopytem w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(14440, 'koKR', 'Obrzędy Matki Ziemi', '$GPrzeszedłeś:Przeszłaś; Obrzędy Matki Ziemi i $gzasłużyłeś:zasłużyłaś; na miejsce w Gromowych Urwiskach.$b$bAle by utrzymać miejsce, o które tak ciężko $gzabiegałeś:zabiegałaś;, musisz wciąż dowodzić swej wartości przed swoim ludem.$b$bJesteśmy łowcami, $n. W dole, w Mulgorze, żyje potężny kodo o imieniu Arra\'chea. Pokaż mi swój kunszt w tropieniu i polowaniu, przynosząc mi Róg Arra\'chea.', 'Bain Krwawe Kopyto w Gromowych Urwiskach chce, żebyś $gprzyniósł:przyniosła; mu Róg Arra\'chea.', '', 'Wróć do Baina Krwawego Kopyta (przywódcy) w Mrocznym Pustkowiu.', '', '', '', '', 0),
(24857, 'koKR', 'Atak na Obóz Naracze', 'Po uważnym przestudiowaniu mapy uświadamiasz sobie, że $gznalazłeś:znalazłaś; plany długotrwałego oblężenia Obozu Naracze, sporządzone przez wodza wojennego Sierściogrzbietów.$b$bWódz Jastrzębi Wiatr z pewnością zechce się o tym dowiedzieć!', 'Zanieś plany ataku Sierściogrzbietów wodzowi Jastrzębiemu Wiatrowi w Obozie Naracze.', '', 'Wróć do wodza Jastrzębiego Wiatru w Obozie Naracze w Mulgorze.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(743, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Wyglądasz na $ggotowego:gotową; do dalszej drogi. Niech wiatr zawsze wieje ci w plecy.', 0),
(745, 'koKR', '$N, dobrze, że $gpotraktowałeś:potraktowałaś; moje zadanie poważnie. Szacunek dla ziemi i jej stworzeń jest ważny. Śmierć i życie tworzą krąg... są koniecznością. Jedno nie istnieje bez drugiego. Poświęć chwilę, by się nad tym zastanowić, i nigdy o tym nie zapominaj.', 0),
(746, 'koKR', 'Dziękuję, $N. To uspokoi zwierzęta Mulgoru. A jeśli duchy pozwolą, nauczy też krasnoludy, że drążenie ziemi nie jest drogą do wiedzy.', 0),
(747, 'koKR', 'Taureni z Naracze dziękują ci, $n. Dobrze się zapowiadasz.', 0),
(748, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Wezmę je i zwiążę ich moc w totemie oczyszczenia.', 0),
(749, 'koKR', 'Każdy bok skrzyni opatrzono pieczęcią Wydziału Górniczego spółki Gitgeszeft. Starannie wypisane na boku notatki wskazują, że zawartość ma trafić do przerobu w jednym z ich głównych zakładów.', 0),
(750, 'koKR', 'Taureni z Naracze dziękują ci za te zapasy, $N. Z twoim łowieckim kunsztem z pewnością pewnego dnia będziesz $gczczony:czczona; w Gromowych Urwiskach.', 0),
(751, 'koKR', 'Rzeczywiście wygląda na to, że spółka Gitgeszeft próbuje ograbić nas z naszych bogactw naturalnych. Dobrze wiedzieć to na pewno. A teraz, jak się zdaje, musimy coś z tym zrobić.', 0),
(752, 'koKR', '$GPrzebyłeś:Przebyłaś; całą tę drogę tylko po to, by pomóc starej kobiecie? No, no, ależ z ciebie skarb!', 0),
(753, 'koKR', 'Widzę, że $gprzyniosłeś:przyniosłaś; ten dzban na prośbę Wszechmatki.$b$bTwoja gotowość, by pomagać innym i troszczyć się o taurenów z Obozu Naracze, każe mi wierzyć, że pewnego dnia przyniesiesz plemieniu chlubę w Gromowych Urwiskach.', 0),
(754, 'koKR', 'Wieść o twoim czynie dotarła do mnie przed chwilą – zwierzęta przy studni już chętnie z niej piją.$b$b$GUczyniłeś:Uczyniłaś; wielką rzecz dla ziemi, $N. I $guczyniłeś:uczyniłaś; wielką rzecz dla ludu taurenów.', 0),
(755, 'koKR', 'Przysłał cię wódz Jastrzębi Wiatr? Podjęcie Obrzędów Matki Ziemi to niemałe wyzwanie...', 0),
(756, 'koKR', 'Dziękuję, $N. Czystość, z jaką polują te zwierzęta, jest niezbędna do stworzenia kolejnego totemu oczyszczenia.$b$bGobliny nigdy nie pojmą różnicy między walką z ziemią a życiem z nią w harmonii.', 0),
(757, 'koKR', '$GPrzeszedłeś:Przeszłaś; pierwszą próbę Obrzędów Matki Ziemi. Plemię będzie z ciebie dumne.', 0),
(758, 'koKR', 'Przodkowie klanu Gromorogich przemówili do mnie we śnie i wychwalali cię za to, czego $gdokonałeś:dokonałaś; przy ich studni.$b$bW podzięce pragną ofiarować ci to...', 0),
(759, 'koKR', 'Bardzo dobrze, $N. Czuję w tej ofierze poświęcenie ziemi, a mój duch wzbiera smutkiem i dumą.', 0),
(760, 'koKR', 'Udało ci się. $GOczyściłeś:Oczyściłaś; studnie i $guleczyłeś:uleczyłaś; naszą ziemię. Wioska Krwawego Kopyta jest ci wdzięczna, $N.$b$bNiech wiatr szepcze o twoich czynach przez sto pór roku i niech wody Mulgoru na zawsze pozostaną czyste.', 0),
(761, 'koKR', 'Wiem, że zebranie tych lotek nie było łatwe, $N. Tym samym $gdowiodłeś:dowiodłaś; swojej wartości. Dobrze mieć cię w Wiosce Krwawego Kopyta.', 0),
(763, 'koKR', 'Wieści od mojego dobrego przyjaciela, wodza Jastrzębiego Wiatru! Ach, po jego rzeźbieniach widzę, że jesteś kimś wyjątkowym.', 0),
(764, 'koKR', 'Chyba trudno ten sygnał źle zrozumieć albo go zlekceważyć, hm? Spółka Gitgeszeft będzie już wiedziała, że nie wolno lekceważyć taurenów ani być tak zuchwałym, by wierzyć, że bez sprzeciwu pozwolimy im rabować otaczające nas bogactwa natury.', 0),
(765, 'koKR', 'Wieść o śmierci tego nikczemnika Fizsprocketa nieco studzi mój gniew. Przejrzę jego rzeczy i sprawdzę, czy znajdę więcej informacji o przyszłych planach spółki Gitgeszeft. Dziękuję za twój trud, $N.', 0),
(766, 'koKR', 'Ach, dziękuję, $N. Z tego, co mi $gprzyniosłeś:przyniosłaś;, przyrządzę lek, który zatrzyma szerzenie się zakażenia, a z czasem całkiem je wyleczy. Zawdzięczam ci życie.$b$bAle nigdy nie zapomnę tego skrzekliwego krzyku, gdy Mazzranache na mnie spadł, ani feerii barw, gdy opadał jego dziób...$b$bUważaj na siebie w podróży.', 0),
(767, 'koKR', 'Wyczułem, że do mnie przyjdziesz. Zawsze rozpoznam kogoś, kto próbuje przejść Obrzędy Matki Ziemi.', 0),
(770, 'koKR', 'Ledwie wierzę moim starym oczom! $GPokonałeś:Pokonałaś; wielkiego wilka, Upiorne Wycie? Patrzę na ciebie z nowym szacunkiem, $N. Masz niezwykłe umiejętności!$b$bPozwól, że coś ci ofiaruję. Moje łowieckie dni już minęły, ale byłbym zaszczycony, gdybyś $gpolował:polowała; z jedną z moich broni.$b$bNiech trafia celnie i przyniesie ci sławę.$b$bI miejmy nadzieję, że duch Upiornego Wycia wreszcie zaznał spokoju.', 0),
(771, 'koKR', 'Widzę, że $gnauczyłeś:nauczyłaś; się zbierać dary naszej świętej ziemi, $N. Uwarzenie Wody jasnowidzów zajmie mi tylko chwilę.', 0),
(772, 'koKR', 'Nie lękaj się, $N. $GPrzeszedłeś:Przeszłaś; Obrzęd Wizji.', 0),
(773, 'koKR', '$GWykazałeś:Wykazałaś; się wielką wytrwałością w dążeniu do przejścia Obrzędów Matki Ziemi, $N.$b$bMy, Duchy przodków, jesteśmy potężnymi taurenami, którzy mężnie oddali życie, by założyć nasze wielkie miasto, Gromowe Urwiska, i go bronić. Niniejszym przekazuję ci obowiązek tej obrony.$b$b$GPrzeszedłeś:Przeszłaś; Obrzęd Mądrości. Wkrocz do Gromowych Urwisk z dumą.', 0),
(775, 'koKR', 'Witaj, $gmłody:młoda; $N. Widzę, że $gtrafiłeś:trafiłaś; do moich drzwi.', 0),
(776, 'koKR', 'Dobra robota! Piękna zdobycz.$b$bWyślę ludzi po truchło, byśmy mogli pozyskać skórę i mięso.$b$b$GOddałeś:Oddałaś; swojemu ludowi wielką przysługę, $N.', 0),
(780, 'koKR', 'Doskonale. Z tych składników wyjdzie wyborny gulasz, a utrata tych dzików powinna dać tym plugawym Sierściogrzbietom słuszną nauczkę.', 0),
(781, 'koKR', 'To naprawdę niepokojące! Ale dzięki tym informacjom możemy wezwać na pomoc naszych braci z Wioski Krwawego Kopyta i udaremnić atak. $GOcaliłeś:Ocaliłaś; życie wielu taurenów, $N.', 0),
(833, 'koKR', 'Dobra robota. $GDałeś:Dałaś; tym plugawym Sierściogrzbietom jasny sygnał. Zastanowią się dwa razy, zanim znów spróbują bezcześcić to święte miejsce.', 0),
(854, 'koKR', 'Dobrze widzieć, że kolejni sojusznicy przybywają nam z pomocą z tak daleka jak Gromowe Urwiska. Raz jeszcze cię witam.', 0),
(861, 'koKR', 'Skorn Biała Chmura to mądry tauren. Poluje od wielu, wielu lat i choć jego ciało jest stare, duch płonie w nim żarliwie. To dla nas zaszczyt, że jest wśród nas.$b$bSkoro Skorn przysłał cię do mnie, ty też musisz mieć ducha łowcy. A zebranie tych pazurów świadczy o twoich rosnących umiejętnościach.$b$bMoże jesteś $ggotów:gotowa;, by wkroczyć na tę ścieżkę.', 0),
(1462, 'koKR', 'Weź to i pamiętaj, że jest to rzecz święta.', 0),
(1519, 'koKR', 'Dobrze, $N. Twój powrót oznacza, że naprawdę jesteś $ggotów:gotowa; na kolejny krok.$B$BSpośród wszystkich żywiołów ziemia jest fundamentem wszystkiego. Jest twoją siłą, twoją wytrzymałością i twoją cierpliwością. Matka Ziemia będzie cię chronić, ale tylko jeśli okażesz jej należny szacunek. Jest podstawą życia, a przestrzegając jej praw, zyskasz większą mądrość. Nigdy nie zapominaj tajemnic, które ci wyjawi.$B$BTeraz przygotuję dla ciebie twoją saptę, a gdy ją przyjmiesz, otworzy się przed tobą nowa ścieżka.', 0),
(1656, 'koKR', 'Ach, futra, na które czekałem. Dziękuję.$B$BDotarły szybciej, niż się spodziewałem. Będą z nich dobre koce dla każdego, kto zechce się tu zatrzymać.$B$BZostań, jak długo zechcesz. Moja karczma jest zawsze otwarta, a cały nasz lud jest tu mile widziany. I nie lekceważ dobrego nocnego wypoczynku – w podróży potrafi zdziałać cuda.', 0),
(2984, 'koKR', 'Hmmm, to Narm cię do mnie przysłał, tak?$b$bCóż, Narmowi zawsze można było ufać, więc musisz być $ggotów:gotowa; przyjąć kolejną saptę – saptę ognia.$b$bJuż widzę to w twoich oczach: ten żar, to pragnienie. $GZakosztowałeś:Zakosztowałaś; mocy, a teraz chcesz jej więcej. Cierpliwości, $N. Pamiętaj, czego nauczyła cię ziemia. Moc i zniszczenie przyjdą łatwo, ale wciąż musisz wiedzieć, kiedy powstrzymać rękę.', 0),
(3091, 'koKR', 'Każdy z nas odgrywa w plemieniu swoją rolę. I każdy z nas musi przejść te same obrzędy. Nigdy nie pozwól, by duma podpowiadała ci co innego.$b$bZostaję tutaj, by szkolić nowych wojowników, którzy szukają chwały w boju i podążają drogą naszych najdawniejszych przodków. Gdy poczujesz się $ggotowy:gotowa;, wróć do mnie, a zrobię, co w mojej mocy, by szkolić cię dalej. Idź z błogosławieństwem plemienia, $N.', 0),
(3092, 'koKR', 'A moim zadaniem jest przygotować cię, ucząc podstaw naszej profesji – jak oswoić zwierzę, jak strzelać ze strzelby i wielu innych umiejętności, które staną się niezbędne.$b$bŁowcy są ważną częścią naszej tradycji i historii, $N. Dobrze zrobisz, pamiętając, jak ważne jest twoje miejsce w plemieniu. Będziesz $gszanowany:szanowana; i $gczczony:czczona;, jeśli dobrze będziesz służyć naszemu ludowi.', 0),
(3093, 'koKR', 'W nadchodzących dniach spotkamy się jeszcze wiele razy. Mam nadzieję, że za każdym razem odejdziesz ode mnie nieco $gpotężniejszy:potężniejsza;... nieco lepiej $gprzygotowany:przygotowana;. Jak Wieczny Płomień, twój duch będzie płonął jasno i gorąco.$b$bIdź teraz, $N. Idź i wystaw się na próbę. Będę tu dla ciebie, gdy mnie potrzebujesz.', 0),
(3094, 'koKR', 'Choć łączy nas wspólna więź, nie oczekuj od nocnych elfów ciepłego przyjęcia. Duma wciąż ogranicza ich wzrok, ale to nie nasza sprawa. Musisz troszczyć się jedynie o nauki Matki Ziemi, a ja przekażę ci, co wiem, w miarę jak będziesz nabierać mądrości.$b$bWracaj do mnie często, $N. Przekonasz się, że Matka Ziemia obdarza niezwykłymi zdolnościami tych, którzy są jej najbardziej oddani.', 0),
(3376, 'koKR', 'Dzięki twemu szybkiemu działaniu sprawiedliwości stało się dziś zadość, $N. Niech ten czyn będzie ostrzeżeniem dla wszystkich, którzy zagrażają naszemu domowi.$b$b$GZasłużyłeś:Zasłużyłaś; na tę nagrodę, która pomoże ci w twojej wędrówce, $gmłody:młoda; $N.', 0),
(6061, 'koKR', 'Matka Ziemia zesłała mi znaki. Dobrze się $gspisałeś:spisałaś;.', 0),
(6087, 'koKR', 'Tak... Matka Ziemia uważa, że jesteś $ggotów:gotowa; na kolejną lekcję.', 0),
(6088, 'koKR', '$GNauczyłeś:Nauczyłaś; się wszystkiego, czego mogłem cię nauczyć, $N. Niech błogosławieństwo Matki Ziemi prowadzi cię przy wyborze towarzysza.$B$BProszę, $N. Teraz dam ci moc oswajania zwierząt, a także przywoływania ich i odsyłania, gdy uznasz to za stosowne. Używaj swoich nowych umiejętności z dumą i oddawaj cześć Matce Ziemi.', 0),
(6089, 'koKR', 'Widzę, że jesteś $gmłodym łowcą:młodą łowczynią;. Tak, mogę cię obdarzyć umiejętnościami potrzebnymi do szkolenia i prowadzenia twojego towarzysza. Nie tylko będziesz $gmógł:mogła; uczyć go nowych zdolności, ale też karmić go, a nawet przywracać do życia, gdyby poległ w walce.$B$BA teraz ruszaj. Niech Matka Ziemia prowadzi cię na twojej ścieżce. Porozmawiamy jeszcze kiedy indziej.', 0),
(7945, 'koKR', 'Szybkie przeszukanie pniaka ujawnia ukrytą w nim szkatułkę! Wygląda na to, że $godnalazłeś:odnalazłaś; swój los!', 0),
(11129, 'koKR', 'Świetna robota, $N! Kyle wrócił do domu, gdy tylko się najadł, i od razu poszedł spać. Dziękuję za pomoc.', 0),
(14438, 'koKR', '$N, dobrze, że $gpotraktowałeś:potraktowałaś; to zadanie poważnie. Szacunek dla ziemi i jej stworzeń jest ważny. Śmierć i życie tworzą krąg... są koniecznością. Jedno nie istnieje bez drugiego. Poświęć chwilę, by się nad tym zastanowić, i nigdy o tym nie zapominaj.', 0),
(24857, 'koKR', 'To naprawdę niepokojące! Ale dzięki tym informacjom możemy wezwać na pomoc naszych braci z Wioski Krwawego Kopyta i udaremnić atak. $GOcaliłeś:Ocaliłaś; życie wielu taurenów, $N.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(743, 'koKR', 'Wichrogniewne harpie to śmiertelnie groźny wróg. Ich siłę w walce przewyższa jedynie ich głód świeżego mięsa.', 0),
(745, 'koKR', 'Gdyby Bladogrzywi bardziej szanowali ziemię i jej mieszkańców, do tego konfliktu nigdy by nie doszło.', 0),
(746, 'koKR', 'Witaj, $N. Masz połamane narzędzia? Krasnoludzkie wykopy rozwścieczą kodo Mulgoru. To bezczeszczenie trzeba powstrzymać!', 0),
(747, 'koKR', 'Dostarczenie plemieniu mięsa i piór to pierwszy krok, by dowieść przed wodzem, że jesteś $gprawdziwym łowcą:prawdziwą łowczynią;.', 0),
(748, 'koKR', 'Masz łapy i szpony, $N?', 0),
(750, 'koKR', 'Jeśli dostarczysz plemieniu futra, przekażę mojemu ojcu, wodzowi Jastrzębiemu Wiatrowi, wieść o twoich hojnych czynach.', 0),
(751, 'koKR', 'Witaj, $N. Czy $gdowiedziałeś:dowiedziałaś; się czegoś nowego o planach i działaniach spółki Gitgeszeft na naszej ziemi?$b$bJeśli zamierzają wyzyskiwać nasze ziemie tak jak inne, Zwiadowcy szybko położą temu kres.', 0),
(753, 'koKR', 'Wyglądasz, jakbyś $gwrócił:wróciła; z równin. Masz jakieś wieści od Wszechmatki Jastrzębiego Wiatru?', 0),
(754, 'koKR', 'Nie zwlekaj, $n. Skażenie trzeba usunąć ze studni Zimowego Kopyta!', 0),
(756, 'koKR', '$N, masz pazury, po które cię posłałem? Ujęcie Wody Gromorogich z każdą godziną jest coraz bardziej skażone!', 0),
(757, 'koKR', 'Czy $gukończyłeś:ukończyłaś; Obrzęd Siły, $N? Potrzebuję dowodu twojego męstwa w walce z wrogiem naszego plemienia, Sierściogrzbietami.', 0),
(758, 'koKR', 'Ujęcie Wody Gromorogich wciąż jest skażone, $n. Proszę, musisz odprawić rytuał!', 0),
(759, 'koKR', '$N. Masz zęby, o które prosiłem?', 0),
(761, 'koKR', 'Czy $gznalazłeś:znalazłaś; pikujące, $N? Masz ich lotki?', 0),
(763, 'koKR', 'Co sprowadza cię do mojej wioski?', 0),
(764, 'koKR', 'Spółce Gitgeszeft odmówiono prawa do wydobycia tu, w Mulgorze, ale wygląda na to, że nie przyjmują odmowy do wiadomości. My, taureni, nie lubimy jednak strzępić języka i mamy inne sposoby, by dać do zrozumienia, co myślimy.', 0),
(765, 'koKR', 'Wrze we mnie gniew na myśl o okrucieństwach, jakich spółka Gitgeszeft gotowa jest się wobec nas dopuścić w imię zysku.', 0),
(766, 'koKR', 'Gorączka się nasila, a mój umysł dryfuje w majaczliwe koszmary... Powinienem był wiedzieć, że nie poradzę sobie z bestią, której nie zdołał pokonać mój dziadek...$b$bMasz składniki na lek? Obawiam się, że jeśli wkrótce nie oczyszczę rany, zakażenie mnie zabije.', 0),
(771, 'koKR', 'Gdy zbierzesz dość kamieni studziennych przy studniach i bursztynowych żołędzi pod drzewami, przygotuję dla ciebie Wodę jasnowidzów.', 0),
(776, 'koKR', 'Czy $gwytropiłeś:wytropiłaś; już Arra\'chea?', 0),
(780, 'koKR', 'Bojowe dziki są coraz bardziej agresywne. Czy $gdałeś:dałaś; im już jasno do zrozumienia, gdzie ich miejsce, i $gprzyniosłeś:przyniosłaś; trochę ryjów i udźców?', 0),
(781, 'koKR', 'Wyglądasz na $gzatroskanego:zatroskaną;, $N. Jakie wieści przynosisz?', 0),
(833, 'koKR', 'Intruzów z Sierściogrzbietów trzeba przepędzić z naszego świętego miejsca pochówku, $n.', 0),
(861, 'koKR', 'Witaj. Jest w tobie coś, co wiele mi mówi. Czy mamy jakąś sprawę, ty i ja?', 0),
(1519, 'koKR', 'Ziemia jest cierpliwa i zaczeka, aż będziesz $ggotów:gotowa;, bo wie, że z czasem wszystko ulega erozji i odradza się na nowo. Taki jest cykl rzeczy. Góry stają się pustyniami. Rzeki stają się kanionami. Ziemia jest najbardziej upartym i najmądrzejszym ze wszystkich żywiołów.$B$BPonad wszystko musisz nauczyć się cierpliwości i wytrwałości. Ziemia wzywa cię teraz, bo czuje, że jesteś $ggotów:gotowa;. Jeśli ci się powiedzie, uznaj to za swoje odrodzenie. Potem nie będzie już powrotu do niewiedzy.', 0),
(1656, 'koKR', 'Tak, $gmój młody przyjacielu:moja młoda przyjaciółko;? Co Kauth może dla ciebie zrobić?$B$BDroga z płaskowyżu dla jednych bywa ogromnym trudem, a dla innych miłym widokiem. Ciekawe, czym jest dla ciebie?', 0),
(3091, 'koKR', 'Ach, nareszcie $gprzybyłeś:przybyłaś;. Nie kłamałem w liściku, $N. My też jesteśmy wyjątkowym rodem, podobnie jak druidzi czy szamani naszego plemienia. Jesteś równie $gważny:ważna;. To nas wzywa się, by bronić naszych granic, polować na centaury i ruszać na wojnę.', 0),
(3092, 'koKR', 'Witaj w Obozie Naracze, $n. Słyszę o tobie dobre rzeczy. Masz silną krew, a wielu starszych już uważa cię za $gbiegłego:biegłą;. Ale to jeszcze sprawdzimy.$b$bRówniny Mulgoru będą przez jakiś czas twoim domem – postaraj się poznać je jak najlepiej. Pewnego dnia wyruszysz do nieznanych krain, by opanować większe umiejętności. Musisz być $ggotów:gotowa;.', 0),
(3093, 'koKR', 'Szybko jak deszcz spadający z nieba – oto stoisz przede mną. Cieszy mnie twój pośpiech. Znaczy to, że rozumiesz, jak ważne jest nasze spotkanie i twoja obecność tutaj. Nie jestem przywódczynią, ale rozumiem żywioły i potrafię rozmawiać z duchami naszego ludu. Nauczę cię robić to samo.', 0),
(3094, 'koKR', 'Jesteś. To dobrze. Duchy naszych przodków niepokoją się w całym Mulgorze i poza nim, lecz nie potrafię powiedzieć dlaczego. Twoim obowiązkiem na zawsze będzie uczyć się słuchać duchów natury i być ich wcieleniem. Pamiętaj o tym.', 0),
(3376, 'koKR', 'Ostrokieł przestanie nas nękać, gdy przyniesiesz mi dowód jego śmierci. Chcę jego głowy, $N.$B$BMy, taureni, żyjemy dla łowów, a nie ma większych łowów niż te na kogoś dość przebiegłego, by może zapolować na nas. Jeśli ci się powiedzie, $gmłody:młoda;, zaczniesz rozumieć, co mam na myśli.', 0),
(6061, 'koKR', 'Ćwicz swoje umiejętności, $N. Oswój dorosłego biegusa równinnego.', 0),
(6087, 'koKR', 'Czy $gznalazłeś:znalazłaś; tropiciela prerii?', 0),
(6088, 'koKR', 'Wkrótce będziesz $ggotów:gotowa;, $N.', 0),
(7662, 'koKR', 'Jeśli przyprowadzisz mi swojego starzejącego się kodo, wymienię go na jednego z nowego stada. Nowy kodo będzie tak samo szybki jak twój stary, ale będzie inaczej wyglądał. Możesz obejrzeć wielkie kodo, które już mamy tu w zagrodzie, i zobaczyć, spośród czego będziesz wybierać.', 0),
(7663, 'koKR', 'Jeśli przyprowadzisz mi swojego starzejącego się kodo, wymienię go na jednego z nowego stada. Nowy kodo będzie tak samo szybki jak twój stary, ale będzie inaczej wyglądał. Możesz obejrzeć wielkie kodo, które już mamy tu w zagrodzie, i zobaczyć, spośród czego będziesz wybierać.', 0),
(7945, 'koKR', 'Ten pniak wygląda jak ten z twojej wizji.', 0),
(11129, 'koKR', '$GZnalazłeś:Znalazłaś; Kyle\'a?', 0),
(24857, 'koKR', 'Wyglądasz na $gzatroskanego:zatroskaną;, $N. Jakie wieści przynosisz?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2981, 0, 'koKR', 'Witaj, $N. Przez lata przewinęło się przed moimi oczami wielu zapalonych taurenów, którzy pragnęli dowieść swej wartości przed plemieniem. Nie wolno zapominać, że zapał nie zastąpi mądrości i doświadczenia.', 0),
(2988, 0, 'koKR', 'Obowiązkiem Zwiadowców jest dbać o bezpieczeństwo wszystkich, którzy podróżują przez równiny Mulgoru. Kto zagraża bezpieczeństwu ojczyzny taurenów, ten naraża się na karę z naszych rąk.', 0),
(2993, 0, 'koKR', 'Ziemia była łaskawa dla naszego ludu, $N. Musimy być wdzięczni za naszą pomyślność.', 0),
(3441, 0, 'koKR', 'Aby zapolować na zwierzę, trzeba je poznać. Trzeba poznać jego zwyczaje i je szanować.$B$BCo innego nie jest polowaniem. Co innego jest zwykłym zabijaniem.', 0);
