INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(352, 'koKR', 'Kierowniku Fizsprocket, w załączeniu przesyłam listę sprzętu, którego zażądałeś, zatwierdzoną przez prezesa Razdunka.$B$BPoprosił mnie, bym przypomniał ci i podkreślił, jak bardzo Spółce Gitgeszeft zależy na rozwinięciu działalności w całym Kalimdorze. Nasze placówki wiertnicze i górnicze na Pustkowiach okazały się dochodowe i wydajne, wciąż jednak czekamy na zadowalające wyniki wydobycia z Mulgoru, który podlega tobie.$B$BZarząd doradczy rozumie trudności związane z uruchomieniem', 0),
(353, 'koKR', 'operacji na tak dużą skalę tuż obok ojczyzny taurenów, nie uważa jednak, by stanowili oni poważną przeszkodę dla naszego ogólnego planu biznesowego w tym rejonie.$B$BZ zadowoleniem przyjmujemy wieść, że na bogatych w minerały równinach Mulgoru rozpoczęto wydobycie. Z tego względu zarząd zatwierdził twoje zamówienie na sprzęt. Uważamy, że poza kopalinami Mulgor ma też wiele do zaoferowania, jeśli chodzi o drewno, dlatego otrzymasz również kilka niszczarek naszego najnowszego modelu oraz surowce do budowy', 0),
(354, 'koKR', 'tartaku. ', 0),
(2441, 'koKR', 'Wiele plemion twierdzi, że talent do władania magią lub rozmowy z przodkami to dar, ale wiedz, $N, że i ty jesteś $gobdarowany:obdarowana;. Niektórym brak siły w ramionach, by dzierżyć potężny oręż. Niektórym brak zręczności, by sparować cios skrytobójcy, a nawet wytrzymałości, by znieść ciosy zadawane przez maga władającego mocą tajemną – ale tobie nie. Jesteś $gsilny:silna;. A ja pomogę ci stać się jeszcze $gsilniejszym:silniejszą;. Znajdź mnie w Obozie Naracze.$B$B-Harutt Gromoróg, nauczyciel wojowników ', 0),
(2453, 'koKR', 'Potężni wojownicy bronią naszego domu. Nasi szamani prowadzą nasze duchy i ukazują nam przeszłość przodków. A nasi druidzi pomagają nam odkrywać wolę Matki Ziemi.$B$BLecz ty należysz do naszych łowców, a nasi łowcy uczą się wielu stron tych ról i łączą je w jedno. Przekonasz się, że uosabiasz serce naszego ludu – jedni z plemienia będą szukać u ciebie przewodnictwa, inni ochrony. Moim obowiązkiem jest dopilnować, byś $gbył gotów:była gotowa; na to. Odszukaj mnie w Obozie Naracze.$B$B-Lanka Dalekostrzał, nauczyciel łowców ', 0),
(2458, 'koKR', 'Zeszłej nocy duchy przyszły do mnie we śnie. Powiedziały mi o twoim przybyciu i o tym, że moim zadaniem będzie ci pomóc. W tym krótkim czasie, który spędzimy razem, mamy wiele do omówienia – rozmowy o naturze, o duchach, o Matce Ziemi, a nawet o nocnych elfach. Lecz lekcje zachowam do twojego przybycia i uczynię wszystko, co w mojej mocy, byś $gbył gotów:była gotowa; na czekające cię próby.$B$BNiech prowadzi cię mądrość. Będę czekać.$B$B-Gart Mglisty Bieg, nauczyciel druidów ', 0),
(2460, 'koKR', 'Witaj, $gmłody:młoda; $N. Wiatry powiedziały mi o twoim przybyciu. Ziemia wysławiała twoją siłę. A teraz pradawne duchy szepczą o twoich przyszłych dokonaniach. Nasz lud zawsze potrzebuje mądrych i wielkich przywódców. Często szuka obu tych cnót właśnie u takich jak my. Jeśli zechcesz, nauczę cię więcej o naszych drogach.$B$BOdszukaj mnie w Obozie Naracze na Płaskowyżu Czerwonej Chmury – wtedy porozmawiamy dłużej.$B$B-Meela Świtokrocz, nauczycielka szamanów ', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(4935, 'koKR', 'Witaj, $N, w Obozie Naracze. Wieść o twoim przybyciu szybko rozeszła się wśród plemienia.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
