INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(947, 'koKR', 'Czekałem na ciebie, $n.', '', 0),
(952, 'koKR', '%s rozpoczyna obrzęd tworzenia...', '', 0),
(953, 'koKR', 'Stało się.', '', 0),
(954, 'koKR', 'Totem jest gotowy, $n.', '', 0),
(955, 'koKR', '%s unosi wysoko przedmioty, które $gprzekazał:przekazała; mu $n...', '', 0),
(1000, 'koKR', '%s używa w rytuale daru, który $gzłożył:złożyła; $n...', '', 0),
(1001, 'koKR', '%s przyjmuje dar, który $gzłożył:złożyła; $n, i zaczyna intonować pieśń...', '', 0),
(1002, 'koKR', '%s przyzywa do siebie moc...', '', 0),
(1003, 'koKR', '%s przemienia przedmioty, które $gprzekazał:przekazała; mu $n, w totem oczyszczenia...', '', 0),
(1004, 'koKR', '%s tworzy nowy totem...', '', 0),
(1005, 'koKR', 'Mam totem oczyszczenia, $n.', '', 0),
(1006, 'koKR', 'Totem jest gotowy. Teraz można oczyścić studnię.', '', 0),
(1007, 'koKR', '$n, stworzyłem totem oczyszczenia.', '', 0),
(1008, 'koKR', 'Dzieło dokonane. Totem jest gotowy.', '', 0),
(1009, 'koKR', 'Stworzyłem totem. Ty, $n, musisz oczyścić studnię.', '', 0),
(1010, 'koKR', 'Przedmioty, które $gofiarowałeś:ofiarowałaś;, były czyste, $n. Ten nowy totem oczyszczenia jest silny.', '', 0),
(1011, 'koKR', '%s zaczyna intonować pieśń, mieszając przed Ogniskiem plemiennym kamienie studzienne i bursztynowe żołędzie.', '', 0),
(1012, 'koKR', 'Woda jasnowidzów jest gotowa do wypicia, $n.', '', 0),
(1364, 'koKR', 'Aby dotrzeć na Rozdroże, $n, idź drogą na wschód, a potem na północ.', '', 0),
(1528, 'koKR', '', '%s wskazuje dzban z wodą stojący na krawędzi studni.', 0),
(2467, 'koKR', 'Podejdź bliżej, dziecko. Za moich czasów słyszałem trzepot serca ofiary, lecz teraz musisz mówić głośniej, jeśli chcesz, bym cię usłyszał.', '', 0),
(2469, 'koKR', 'Opowiedz mi jakąś historię, Skornie.', 'Opowiedz mi jakąś historię, Skornie.', 0),
(2470, 'koKR', '$gZabiłeś:Zabiłaś; Upiorne Wycie. Ale z ciebie zuch!', '', 0),
(2471, 'koKR', 'Przez wiele, wiele pór roku przemierzałem te równiny. Polowałem na wielkie bestie. I nikt nigdy mnie nie pokonał... dopóki nie stanąłem przed Upiornym Wyciem.$B$BDawno temu ten ogromny wilk był sprzymierzeńcem taurenów i dzielnie walczył z Płonącym Legionem. Lecz pewien demon ciężko go zranił, a rana w jego ciele nigdy się nie zagoiła. W końcu... doprowadziła Upiorne Wycie do szaleństwa.$B$BTeraz przemierza równiny w męce, szukając kresu swojego bólu. Ku mojemu wstydowi, gdy walczyliśmy, zabrakło mi sił, by go zabić...', '', 0),
(2825, 'koKR', 'Jak wiatr na równinach, zawsze jesteś tu mile $gwidziany:widziana;.', 'Jak wiatr na równinach, zawsze jesteś tu mile $gwidziany:widziana;.', 0),
(5969, 'koKR', 'Witaj na Rozdrożu, $N. Nazywam się Thork – w imieniu wodza dowodzę tutejszą obroną.$B$BCzuj się jak u siebie. Dopóki pilnujesz własnych spraw, nikt nie powinien mieć nic przeciwko temu, że zajmiesz tu trochę miejsca.$B$BWiele zagraża tu naszemu bezpieczeństwu. Jeśli już $gpoznałeś:poznałaś; okolicę, porozmawiaj z innymi – może mają dla ciebie jakieś zadania.', '', 0),
(6663, 'koKR', 'Ach, aby odwiedzić kogoś takiego, musisz udać się na wyżyny Gromowych Urwisk. Idź ścieżką na północ z Wioski Krwawego Kopyta. U podnóża urwisk znajdziesz windę, która zawiezie cię na górę. Gdy tam dotrzesz, zapytaj o dalszą drogę któregoś ze strażników urwisk.', 'Ach, aby odwiedzić kogoś takiego, musisz udać się na wyżyny Gromowych Urwisk. Idź ścieżką na północ z Wioski Krwawego Kopyta. U podnóża urwisk znajdziesz windę, która zawiezie cię na górę. Gdy tam dotrzesz, zapytaj o dalszą drogę któregoś ze strażników urwisk.', 0),
(6665, 'koKR', 'W wiosce nie ma takiego miejsca. Znajdziesz je za to na strzelistych wyżynach Gromowych Urwisk. Idź drogą na północ z Wioski Krwawego Kopyta, aż dotrzesz do podnóża urwisk. Tam wjedź windą na górę i porozmawiaj ze strażnikiem urwisk. Niech czuwają nad tobą przodkowie.', 'W wiosce nie ma takiego miejsca. Znajdziesz je za to na strzelistych wyżynach Gromowych Urwisk. Idź drogą na północ z Wioski Krwawego Kopyta, aż dotrzesz do podnóża urwisk. Tam wjedź windą na górę i porozmawiaj ze strażnikiem urwisk. Niech czuwają nad tobą przodkowie.', 0),
(6666, 'koKR', 'Mistrz wiwern jest w wielkim mieście Gromowe Urwiska, na północy. Wjedź windą od podnóża Gromowych Urwisk na górę i zapytaj któregoś ze strażników urwisk o dalsze wskazówki.', 'Mistrz wiwern jest w wielkim mieście Gromowe Urwiska, na północy. Wjedź windą od podnóża Gromowych Urwisk na górę i zapytaj któregoś ze strażników urwisk o dalsze wskazówki.', 0),
(6667, 'koKR', 'Nic tak nie wyzwala ducha jak szybowanie po niebie. Takie miejsce jest w Gromowych Urwiskach, naszym wielkim ośrodku plemiennym. Zaprowadzi cię tam droga na północ z Wioski Krwawego Kopyta. Gdy wjedziesz windą na górę, porozmawiaj z którymś ze strażników urwisk, a wskaże ci dalszą drogę.', 'Nic tak nie wyzwala ducha jak szybowanie po niebie. Takie miejsce jest w Gromowych Urwiskach, naszym wielkim ośrodku plemiennym. Zaprowadzi cię tam droga na północ z Wioski Krwawego Kopyta. Gdy wjedziesz windą na górę, porozmawiaj z którymś ze strażników urwisk, a wskaże ci dalszą drogę.', 0),
(6668, 'koKR', 'Karczmarz Kauth zadba o twoje potrzeby. Znajdziesz go w jednym z długich domów po zachodniej stronie wioski.', 'Karczmarz Kauth zadba o twoje potrzeby. Znajdziesz go w jednym z długich domów po zachodniej stronie wioski.', 0),
(6669, 'koKR', 'Na wszystko jest czas i miejsce, także na odpoczynek. Po zachodniej stronie Wioski Krwawego Kopyta karczmarz Kauth prowadzi długi dom dla tych, którzy szukają wytchnienia. Tam go znajdziesz.', 'Na wszystko jest czas i miejsce, także na odpoczynek. Po zachodniej stronie Wioski Krwawego Kopyta karczmarz Kauth prowadzi długi dom dla tych, którzy szukają wytchnienia. Tam go znajdziesz.', 0),
(6670, 'koKR', 'Szukasz rady Genni Runicznego Totemu. Znajdziesz ją w dużym namiocie po wschodniej stronie wioski.', 'Szukasz rady Genni Runicznego Totemu. Znajdziesz ją w dużym namiocie po wschodniej stronie wioski.', 0),
(6671, 'koKR', 'Droga druida jest siostrą drogi szamana. Gennia Runiczny Totem jest przesiąknięta tą wiedzą. Odszukaj ją w dużym namiocie po wschodniej stronie Wioski Krwawego Kopyta.', 'Droga druida jest siostrą drogi szamana. Gennia Runiczny Totem jest przesiąknięta tą wiedzą. Odszukaj ją w dużym namiocie po wschodniej stronie Wioski Krwawego Kopyta.', 0),
(6672, 'koKR', 'Yaw Ostrogrzywy czeka na ciebie na północnym skraju wioski. Nauczy cię dróg łowcy.', 'Yaw Ostrogrzywy czeka na ciebie na północnym skraju wioski. Nauczy cię dróg łowcy.', 0),
(6673, 'koKR', 'Nauczyć się być jednym z Naturą w oczach Matki Ziemi – to powód do dumy. Jeśli pragniesz poznać drogi łowcy, odszukaj Yawa Ostrogrzywego na północnym krańcu Wioski Krwawego Kopyta.', 'Nauczyć się być jednym z Naturą w oczach Matki Ziemi – to powód do dumy. Jeśli pragniesz poznać drogi łowcy, odszukaj Yawa Ostrogrzywego na północnym krańcu Wioski Krwawego Kopyta.', 0),
(6674, 'koKR', 'Po wschodniej stronie Wioski Krwawego Kopyta stoi duży namiot. Znajdziesz tam Narma Niebiańskiego Pędu, który na ciebie czeka.', 'Po wschodniej stronie Wioski Krwawego Kopyta stoi duży namiot. Znajdziesz tam Narma Niebiańskiego Pędu, który na ciebie czeka.', 0),
(6675, 'koKR', 'Jest w wiosce mędrzec, który zwie się Narm Niebiański Pęd. Poprowadzi cię dalej ścieżką szamana.', 'Jest w wiosce mędrzec, który zwie się Narm Niebiański Pęd. Poprowadzi cię dalej ścieżką szamana.', 0),
(6676, 'koKR', 'Krang Kamienne Kopyto stoi pośrodku swojego kręgu ćwiczebnego w południowo-wschodnim rogu wioski.', 'Krang Kamienne Kopyto stoi pośrodku swojego kręgu ćwiczebnego w południowo-wschodnim rogu wioski.', 0),
(6677, 'koKR', 'Jeśli łakniesz drogi wojownika, musisz odszukać Kranga Kamiennego Kopyta. Znajdziesz go w południowo-wschodnim rogu wioski, w jego kręgu ćwiczebnym, gdzie często szkoli innych uczniów.', 'Jeśli łakniesz drogi wojownika, musisz odszukać Kranga Kamiennego Kopyta. Znajdziesz go w południowo-wschodnim rogu wioski, w jego kręgu ćwiczebnym, gdzie często szkoli innych uczniów.', 0),
(6678, 'koKR', 'W Wiosce Krwawego Kopyta nie mamy nauczyciela alchemii, ale jest jeden w Gromowych Urwiskach, na północy. Idź tam drogą, a gdy dotrzesz na górę, zapytaj o drogę któregoś ze strażników urwisk.', 'W Wiosce Krwawego Kopyta nie mamy nauczyciela alchemii, ale jest jeden w Gromowych Urwiskach, na północy. Idź tam drogą, a gdy dotrzesz na górę, zapytaj o drogę któregoś ze strażników urwisk.', 0),
(6679, 'koKR', 'Tworzenie z owoców Matki Ziemi mikstur, które wspierają nas w odwiecznej walce, to godne zajęcie. Aby się tego nauczyć, musisz udać się na północ, do naszego wielkiego domu, Gromowych Urwisk. Gdy dotrzesz na górę, poproś o pomoc któregoś ze strażników urwisk – wskaże ci dokładniej drogę.', 'Tworzenie z owoców Matki Ziemi mikstur, które wspierają nas w odwiecznej walce, to godne zajęcie. Aby się tego nauczyć, musisz udać się na północ, do naszego wielkiego domu, Gromowych Urwisk. Gdy dotrzesz na górę, poproś o pomoc któregoś ze strażników urwisk – wskaże ci dokładniej drogę.', 0),
(6680, 'koKR', 'W naszym wielkim domu, Gromowych Urwiskach, na północy, jest nauczyciel kowalstwa. Jeśli szukasz tej wiedzy, udaj się tam i zapytaj o drogę któregoś ze strażników urwisk.', 'W naszym wielkim domu, Gromowych Urwiskach, na północy, jest nauczyciel kowalstwa. Jeśli szukasz tej wiedzy, udaj się tam i zapytaj o drogę któregoś ze strażników urwisk.', 0),
(6681, 'koKR', 'Pragniesz kształtować kości Matki Ziemi w narzędzia, które wesprą Hordę. Dobrze, dobrze. Idź ścieżką na północ z Wioski Krwawego Kopyta, aż dotrzesz do windy prowadzącej na szczyt Gromowych Urwisk. Strażnik urwisk udzieli ci tam dalszej pomocy.', 'Pragniesz kształtować kości Matki Ziemi w narzędzia, które wesprą Hordę. Dobrze, dobrze. Idź ścieżką na północ z Wioski Krwawego Kopyta, aż dotrzesz do windy prowadzącej na szczyt Gromowych Urwisk. Strażnik urwisk udzieli ci tam dalszej pomocy.', 0),
(6682, 'koKR', 'Pyalla Cichego Kroku znajdziesz w wielkim namiocie w północno-zachodnim rogu wioski. Nauczy cię tego, czego pragniesz.', 'Pyalla Cichego Kroku znajdziesz w wielkim namiocie w północno-zachodnim rogu wioski. Nauczy cię tego, czego pragniesz.', 0),
(6683, 'koKR', 'Aż ślinka cieknie na samą myśl. Pyall Cichy Krok to najlepszy kucharz w Wiosce Krwawego Kopyta. Znajdziesz go w wielkim namiocie w północno-zachodnim rogu wioski.', 'Aż ślinka cieknie na samą myśl. Pyall Cichy Krok to najlepszy kucharz w Wiosce Krwawego Kopyta. Znajdziesz go w wielkim namiocie w północno-zachodnim rogu wioski.', 0),
(6684, 'koKR', 'W takim razie, przyjacielu, twoja podróż wiedzie na północ, do Gromowych Urwisk. Gdy tam dotrzesz, zasięgnij rady któregoś ze strażników urwisk – powie ci dokładnie, gdzie znaleźć tego, kogo szukasz.', 'W takim razie, przyjacielu, twoja podróż wiedzie na północ, do Gromowych Urwisk. Gdy tam dotrzesz, zasięgnij rady któregoś ze strażników urwisk – powie ci dokładnie, gdzie znaleźć tego, kogo szukasz.', 0),
(6685, 'koKR', 'Taka mądrość skrywa się w tajemnicy, którą można zgłębić tylko w wielkich Gromowych Urwiskach. Idź ścieżką na północ z Wioski Krwawego Kopyta, aż dotrzesz do windy u podnóża urwisk. Wjedź nią na górę i poproś o dalszą pomoc któregoś ze strażników urwisk.', 'Taka mądrość skrywa się w tajemnicy, którą można zgłębić tylko w wielkich Gromowych Urwiskach. Idź ścieżką na północ z Wioski Krwawego Kopyta, aż dotrzesz do windy u podnóża urwisk. Wjedź nią na górę i poproś o dalszą pomoc któregoś ze strażników urwisk.', 0),
(6686, 'koKR', 'Vira Młode Kopyto przyjmuje w długim domu po zachodniej stronie wioski.', 'Vira Młode Kopyto przyjmuje w długim domu po zachodniej stronie wioski.', 0),
(6687, 'koKR', 'Bandaże, odtrutki i tym podobne to nieodzowne potrzeby życia na równinach. Vira Młode Kopyto może przekazać ci tę wiedzę. Znajdziesz ją w długim domu po zachodniej stronie Wioski Krwawego Kopyta.', 'Bandaże, odtrutki i tym podobne to nieodzowne potrzeby życia na równinach. Vira Młode Kopyto może przekazać ci tę wiedzę. Znajdziesz ją w długim domu po zachodniej stronie Wioski Krwawego Kopyta.', 0),
(6688, 'koKR', 'Szukasz Uthana Cichej Wody. Znajdziesz go na zachód od wioski, gdzie łowi ryby nad Jeziorem Kamiennego Byka.', 'Szukasz Uthana Cichej Wody. Znajdziesz go na zachód od wioski, gdzie łowi ryby nad Jeziorem Kamiennego Byka.', 0),
(6689, 'koKR', 'Daj bykowi rybę, a nakarmisz go na jeden dzień. Naucz byka łowić, a nakarmisz go na całe życie. Uthan Cicha Woda nauczy cię łowić ryby. Szukaj jego mądrości na zachód od Wioski Krwawego Kopyta, na brzegach Jeziora Kamiennego Byka.', 'Daj bykowi rybę, a nakarmisz go na jeden dzień. Naucz byka łowić, a nakarmisz go na całe życie. Uthan Cicha Woda nauczy cię łowić ryby. Szukaj jego mądrości na zachód od Wioski Krwawego Kopyta, na brzegach Jeziora Kamiennego Byka.', 0),
(6690, 'koKR', 'Jeśli pragniesz poznać tajniki ziołozbieractwa, musisz udać się do Gromowych Urwisk. Idź drogą na północ z Wioski Krwawego Kopyta i wjedź windą na szczyt. Tam możesz poprosić o dalszą pomoc strażnika urwisk.', 'Jeśli pragniesz poznać tajniki ziołozbieractwa, musisz udać się do Gromowych Urwisk. Idź drogą na północ z Wioski Krwawego Kopyta i wjedź windą na szczyt. Tam możesz poprosić o dalszą pomoc strażnika urwisk.', 0),
(6691, 'koKR', 'Są tacy, którzy nauczą cię ziołozbieractwa w wielkim domu, Gromowych Urwiskach, daleko na północy. Aby tam dotrzeć, idź drogą wychodzącą z wioski, a u podnóża urwisk wjedź windą na szczyt. Jest tam wielu strażników urwisk, którzy wskażą ci dalszą drogę.', 'Są tacy, którzy nauczą cię ziołozbieractwa w wielkim domu, Gromowych Urwiskach, daleko na północy. Aby tam dotrzeć, idź drogą wychodzącą z wioski, a u podnóża urwisk wjedź windą na szczyt. Jest tam wielu strażników urwisk, którzy wskażą ci dalszą drogę.', 0),
(6692, 'koKR', 'Chaw Mocna Skóra mieszka w wielkim namiocie w północno-zachodnim rogu wioski. Nauczy cię tego, co na razie musisz wiedzieć o garbarstwie.', 'Chaw Mocna Skóra mieszka w wielkim namiocie w północno-zachodnim rogu wioski. Nauczy cię tego, co na razie musisz wiedzieć o garbarstwie.', 0),
(6693, 'koKR', 'Gdy wykorzystujemy skóry zwierząt, które musimy zabić dla pożywienia lub ochrony, oddajemy cześć Matce Ziemi i szacunek zwierzęciu. Chaw Mocna Skóra może cię tego nauczyć. Znajdziesz go w wielkim namiocie w północno-zachodnim rogu Wioski Krwawego Kopyta.', 'Gdy wykorzystujemy skóry zwierząt, które musimy zabić dla pożywienia lub ochrony, oddajemy cześć Matce Ziemi i szacunek zwierzęciu. Chaw Mocna Skóra może cię tego nauczyć. Znajdziesz go w wielkim namiocie w północno-zachodnim rogu Wioski Krwawego Kopyta.', 0),
(6694, 'koKR', 'Hmm, myślę, że aby się tego nauczyć, musisz udać się do Gromowych Urwisk. Idź drogą na północ z Wioski Krwawego Kopyta. Zaprowadzi cię do podnóża Gromowych Urwisk. Wjedź windą na górę i poproś o dalszą pomoc któregokolwiek ze strażników urwisk.', 'Hmm, myślę, że aby się tego nauczyć, musisz udać się do Gromowych Urwisk. Idź drogą na północ z Wioski Krwawego Kopyta. Zaprowadzi cię do podnóża Gromowych Urwisk. Wjedź windą na górę i poproś o dalszą pomoc któregokolwiek ze strażników urwisk.', 0),
(6695, 'koKR', 'Podobno w Gromowych Urwiskach, na północy, jest nauczycielka górnictwa. Idź drogą wychodzącą z wioski, a gdy tam dotrzesz, wjedź windą na szczyt. Dalej pomoże ci każdy ze strażników urwisk.', 'Podobno w Gromowych Urwiskach, na północy, jest nauczycielka górnictwa. Idź drogą wychodzącą z wioski, a gdy tam dotrzesz, wjedź windą na szczyt. Dalej pomoże ci każdy ze strażników urwisk.', 0),
(6696, 'koKR', 'Yonna Głębokiego Cięcia znajdziesz w wielkim namiocie w północno-zachodnim rogu Wioski Krwawego Kopyta.', 'Yonna Głębokiego Cięcia znajdziesz w wielkim namiocie w północno-zachodnim rogu Wioski Krwawego Kopyta.', 0),
(6697, 'koKR', 'Ach tak, skórowanie. Nikt nie włada nożem do skórowania lepiej niż Yonn Głębokie Cięcie. Znajdziesz go w wielkim namiocie w północno-zachodnim rogu wioski.', 'Ach tak, skórowanie. Nikt nie włada nożem do skórowania lepiej niż Yonn Głębokie Cięcie. Znajdziesz go w wielkim namiocie w północno-zachodnim rogu wioski.', 0),
(6698, 'koKR', 'Niestety, w Wiosce Krwawego Kopyta nie ma nikogo, kto uczy krawiectwa, ale nauczyciela znajdziesz w Gromowych Urwiskach. Idź ścieżką na północ z wioski, aż dotrzesz do wind. Wjedź jedną z nich na szczyt i zapytaj o drogę któregoś ze strażników urwisk.', 'Niestety, w Wiosce Krwawego Kopyta nie ma nikogo, kto uczy krawiectwa, ale nauczyciela znajdziesz w Gromowych Urwiskach. Idź ścieżką na północ z wioski, aż dotrzesz do wind. Wjedź jedną z nich na szczyt i zapytaj o drogę któregoś ze strażników urwisk.', 0),
(6699, 'koKR', 'Krawiectwo, powiadasz? Hmm. Ach tak, oczywiście. Musisz udać się do Gromowych Urwisk, na północ. Dojdziesz tam ścieżką wychodzącą z wioski. Gdy dotrzesz do podnóża urwisk, wjedź windą na szczyt i porozmawiaj z którymś ze strażników urwisk.', 'Krawiectwo, powiadasz? Hmm. Ach tak, oczywiście. Musisz udać się do Gromowych Urwisk, na północ. Dojdziesz tam ścieżką wychodzącą z wioski. Gdy dotrzesz do podnóża urwisk, wjedź windą na szczyt i porozmawiaj z którymś ze strażników urwisk.', 0),
(7170, 'koKR', 'Kogoś szukam, $N. Proszę, zostaw mnie w spokoju... muszę ich odnaleźć, to ważne.', '', 0),
(7463, 'koKR', 'Strzeżemy równowagi, jak uczy Cenarius, $N. Jego światło jest jak latarnia wskazująca nam drogę i musimy uczynić wszystko, co w naszej mocy, by to światło zachować.', 'Strzeżemy równowagi, jak uczy Cenarius, $N. Jego światło jest jak latarnia wskazująca nam drogę i musimy uczynić wszystko, co w naszej mocy, by to światło zachować.', 0),
(7512, 'koKR', 'Kodo, przyjacielu! Ułożone od młodu i wychowane na Złotych Równinach Mulgoru, te wspaniałe zwierzęta będą jeszcze wspanialszymi wierzchowcami! Proszę, obejrzyj moją ofertę i przekonaj się $gsam:sama;, dlaczego my, taureni, polegamy na tych niezwykłych stworzeniach!', 'Kodo, przyjacielu! Ułożone od młodu i wychowane na Złotych Równinach Mulgoru, te wspaniałe zwierzęta będą jeszcze wspanialszymi wierzchowcami! Proszę, obejrzyj moją ofertę i przekonaj się $gsam:sama;, dlaczego my, taureni, polegamy na tych niezwykłych stworzeniach!', 0),
(7533, 'koKR', 'Mogę nauczyć cię tajników jazdy na kodo, o ile masz dość złota, by opłacić lekcję!', 'Mogę nauczyć cię tajników jazdy na kodo, o ile masz dość złota, by opłacić lekcję!', 0),
(7967, 'koKR', 'Mięso, skóra, kości... dobry łowca niczego nie marnuje. Każdy skrawek skóry można wykorzystać, choćby do wzmocnienia pancerza sojusznika. Tak oto każdy z nas jest silny w pojedynkę, lecz razem stajemy się niezwyciężeni.', '', 0),
(7969, 'koKR', 'Żyjemy i umieramy, a ziemia trwa, wieczna, niewzruszona naszym przemijaniem. Dlatego ziemia nie może należeć do nas, $n. To my należymy do niej. Dlatego chronimy ziemię, bo bez niej nie mamy nadziei na przetrwanie.', '', 0),
(8295, 'koKR', 'Pragnę dalszych nauk druidzkich, by lepiej zrozumieć wolę Matki Ziemi.', 'Pragnę dalszych nauk druidzkich, by lepiej zrozumieć wolę Matki Ziemi.', 0),
(8416, 'koKR', 'Mój lud cię nie zna. Kodo to potężny wierzchowiec, owoc miłości i troski mojego ludu – nie oddaje się go obcym. Dopóki nie zdobędziesz u starszyzny Gromowych Urwisk poziomu Wywyższony, nie mogę sprzedać ci kodo.', 'Mój lud cię nie zna. Kodo to potężny wierzchowiec, owoc miłości i troski mojego ludu – nie oddaje się go obcym. Dopóki nie zdobędziesz u starszyzny Gromowych Urwisk poziomu Wywyższony, nie mogę sprzedać ci kodo.', 0),
(8437, 'koKR', 'Zanim nauczę cię jazdy wierzchem, musisz osiągnąć poziom Wywyższony u taurenów z Gromowych Urwisk, $N.', 'Zanim nauczę cię jazdy wierzchem, musisz osiągnąć poziom Wywyższony u taurenów z Gromowych Urwisk, $N.', 0),
(8513, 'koKR', 'Ach tak, musisz odnaleźć Seikwę. Ostatnio stała chyba przed karczmą.', 'Ach tak, musisz odnaleźć Seikwę. Ostatnio stała chyba przed karczmą.', 0),
(8514, 'koKR', 'Seikwa zaopiekuje się twoimi zwierzęcymi przyjaciółmi, gdy zajdzie potrzeba. Szukaj jej przed karczmą.', 'Seikwa zaopiekuje się twoimi zwierzęcymi przyjaciółmi, gdy zajdzie potrzeba. Szukaj jej przed karczmą.', 0),
(22068, 'koKR', '%s wyje z zachwytu na widok swojego obiadu!', '', 0),
(22069, 'koKR', '%s zjada swój obiad.', '', 0),
(22166, 'koKR', 'Gdzie jest ten pies?', '', 0),
(22167, 'koKR', 'Pomożesz mi odnaleźć mojego psa?', '', 0),
(22168, 'koKR', 'Tak bardzo tęsknię za moim psem!', '', 0),
(31565, 'koKR', 'Odszukaj Poshkena Twardą Oprawę przy Źródłach Objawień, pod Wzniesieniem Ducha.', 'Odszukaj Poshkena Twardą Oprawę przy Źródłach Objawień, pod Wzniesieniem Ducha.', 0),
(38248, 'koKR', 'Ze wschodu wieje zły wiatr, $N.', '', 0),
(50751, 'koKR', 'Tylko najdzielniejsi i najbardziej prawi z plemienia mogą dostąpić zaszczytu spoczynku przy Czerwonych Skałach.', '', 0);
